  (3,    '3% (Gold, silver, jewellery)',       true,  40),
  (5,    '5% (Merit rate)',                    true,  50),
  (18,   '18% (Standard rate)',                true,  60),
  (40,   '40% (Sin and luxury goods)',         true,  70),
