-- ════════════════════════════════════════════════════════════════════════════
-- EkDum · 03 · Inventory ledger and purchases
-- ════════════════════════════════════════════════════════════════════════════

-- ── Stock ledger ────────────────────────────────────────────────────────────
-- stock_movements is the source of truth and is append-only.
-- stock_levels is a running total maintained ONLY by the trigger below.

create table public.stock_movements (
  id              uuid primary key default gen_random_uuid(),
  business_id     uuid not null references public.businesses (id) on delete cascade,
  outlet_id       uuid not null references public.outlets (id) on delete restrict,
  product_id      uuid not null references public.products (id) on delete restrict,
  quantity_delta  numeric(12,3) not null check (quantity_delta <> 0),
  movement_type   text not null check (movement_type in (
                    'opening', 'purchase', 'sale', 'sale_return', 'adjustment', 'sale_cancel', 'purchase_cancel')),
  source_table    text,
  source_id       uuid,
  reason          text,
  note            text,
  created_by      uuid references auth.users (id) on delete set null,
  created_at      timestamptz not null default now()
);

create index stock_movements_product_idx on public.stock_movements (product_id, outlet_id, created_at desc);
create index stock_movements_business_created_idx on public.stock_movements (business_id, created_at desc);
create index stock_movements_outlet_idx on public.stock_movements (outlet_id);
create index stock_movements_source_idx on public.stock_movements (source_table, source_id);

create table public.stock_levels (
  product_id   uuid not null references public.products (id) on delete cascade,
  outlet_id    uuid not null references public.outlets (id) on delete cascade,
  business_id  uuid not null references public.businesses (id) on delete cascade,
  quantity     numeric(14,3) not null default 0,
  updated_at   timestamptz not null default now(),
  primary key (product_id, outlet_id)
);

create index stock_levels_outlet_idx on public.stock_levels (outlet_id);
create index stock_levels_business_idx on public.stock_levels (business_id);

create or replace function public.apply_stock_movement()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not exists (
    select 1 from public.products p where p.id = new.product_id and p.business_id = new.business_id
  ) or not exists (
    select 1 from public.outlets o where o.id = new.outlet_id and o.business_id = new.business_id
  ) then
    raise exception 'Stock movement product/outlet does not belong to the business';
  end if;

  insert into public.stock_levels as sl (product_id, outlet_id, business_id, quantity, updated_at)
  values (new.product_id, new.outlet_id, new.business_id, new.quantity_delta, now())
  on conflict (product_id, outlet_id)
  do update set quantity = sl.quantity + excluded.quantity, updated_at = now();
  return new;
end;
$$;

create trigger stock_movements_apply after insert on public.stock_movements
  for each row execute function public.apply_stock_movement();

create or replace function public.forbid_change()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  -- Deleting a whole business (or product) is allowed to cascade.
  if tg_op = 'DELETE' and not exists (select 1 from public.businesses b where b.id = old.business_id) then
    return old;
  end if;
  raise exception '% rows are append-only and cannot be %', tg_table_name, lower(tg_op) || 'd';
end;
$$;

create trigger stock_movements_immutable before update or delete on public.stock_movements
  for each row execute function public.forbid_change();

-- Raise when a stock decrease would take the level below zero and the business forbids it.
create or replace function public.assert_stock_available(p_business_id uuid, p_outlet_id uuid, p_product_id uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_qty numeric;
  v_name text;
begin
  if (select allow_negative_stock from public.businesses where id = p_business_id) then
    return;
  end if;
  select quantity into v_qty from public.stock_levels
  where product_id = p_product_id and outlet_id = p_outlet_id;
  if coalesce(v_qty, 0) < 0 then
    select name into v_name from public.products where id = p_product_id;
    raise exception 'Not enough stock for "%"', v_name using errcode = 'P0001', hint = 'insufficient_stock';
  end if;
end;
$$;

create or replace function public.set_opening_stock(p_product_id uuid, p_outlet_id uuid, p_quantity numeric)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_product public.products;
begin
  select * into v_product from public.products where id = p_product_id;
  if not found
     or not public.has_perm(v_product.business_id, 'products.manage')
     or not public.can_access_outlet(p_outlet_id) then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if p_quantity is null or p_quantity <= 0 then
    return;
  end if;
  if exists (select 1 from public.stock_movements where product_id = p_product_id and outlet_id = p_outlet_id) then
    raise exception 'Opening stock can only be set before any other stock movement. Use a stock adjustment instead.';
  end if;

  insert into public.stock_movements (business_id, outlet_id, product_id, quantity_delta, movement_type,
                                      source_table, source_id, note, created_by)
  values (v_product.business_id, p_outlet_id, p_product_id, round(p_quantity, 3), 'opening',
          'products', p_product_id, 'Opening stock', auth.uid());
end;
$$;

create or replace function public.adjust_stock(
  p_outlet_id uuid,
  p_product_id uuid,
  p_quantity_delta numeric,
  p_reason text,
  p_note text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_product public.products;
  v_before numeric;
  v_movement uuid;
begin
  select * into v_product from public.products where id = p_product_id;
  if not found
     or not public.has_perm(v_product.business_id, 'inventory.adjust')
     or not public.can_access_outlet(p_outlet_id) then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if p_reason is null or p_reason not in ('damage', 'theft', 'recount', 'other') then
    raise exception 'A reason is required: damage, theft, recount or other';
  end if;
  if p_reason = 'other' and length(trim(coalesce(p_note, ''))) = 0 then
    raise exception 'Please add a note explaining the adjustment';
  end if;
  if p_quantity_delta is null or round(p_quantity_delta, 3) = 0 then
    raise exception 'Adjustment quantity cannot be zero';
  end if;
  if not v_product.track_inventory then
    raise exception 'Stock is not tracked for this product';
  end if;

  select coalesce(quantity, 0) into v_before from public.stock_levels
  where product_id = p_product_id and outlet_id = p_outlet_id;
  v_before := coalesce(v_before, 0);

  insert into public.stock_movements (business_id, outlet_id, product_id, quantity_delta, movement_type,
                                      source_table, reason, note, created_by)
  values (v_product.business_id, p_outlet_id, p_product_id, round(p_quantity_delta, 3), 'adjustment',
          'stock_adjustments', p_reason, nullif(trim(coalesce(p_note, '')), ''), auth.uid())
  returning id into v_movement;

  if p_quantity_delta < 0 then
    perform public.assert_stock_available(v_product.business_id, p_outlet_id, p_product_id);
  end if;

  perform public.write_audit(v_product.business_id, auth.uid(), 'stock.adjusted', 'stock_movements', v_movement,
    jsonb_build_object('quantity', v_before),
    jsonb_build_object('quantity', v_before + round(p_quantity_delta, 3), 'delta', round(p_quantity_delta, 3),
                       'reason', p_reason, 'note', p_note, 'product_id', p_product_id, 'outlet_id', p_outlet_id,
                       'product', v_product.name));
  return v_movement;
end;
$$;

-- ── Purchases ───────────────────────────────────────────────────────────────

create table public.purchase_bills (
  id                      uuid primary key default gen_random_uuid(),
  business_id             uuid not null references public.businesses (id) on delete cascade,
  outlet_id               uuid not null references public.outlets (id) on delete restrict,
  -- Nullable while a draft is being prepared (e.g. only the bill photo is attached so far).
  vendor_id               uuid references public.vendors (id) on delete restrict,
  vendor_invoice_number   text,
  vendor_invoice_date     date,
  financial_year          text,
  place_of_supply_state   text check (place_of_supply_state is null or place_of_supply_state ~ '^[0-9]{2}$'),
  is_inter_state          boolean not null default false,
  status                  text not null default 'draft' check (status in ('draft', 'posted', 'cancelled')),
  subtotal_paise          bigint not null default 0,
  discount_paise          bigint not null default 0,
  taxable_paise           bigint not null default 0,
  cgst_paise              bigint not null default 0,
  sgst_paise              bigint not null default 0,
  igst_paise              bigint not null default 0,
  cess_paise              bigint not null default 0,
  round_off_paise         bigint not null default 0,
  total_paise             bigint not null default 0 check (total_paise >= 0),
  amount_paid_paise       bigint not null default 0 check (amount_paid_paise >= 0),
  payment_status          text not null default 'unpaid' check (payment_status in ('unpaid', 'partial', 'paid')),
  attachment_paths        text[] not null default '{}',
  notes                   text,
  posted_at               timestamptz,
  posted_by               uuid references auth.users (id) on delete set null,
  cancelled_at            timestamptz,
  cancelled_by            uuid references auth.users (id) on delete set null,
  cancel_reason           text,
  created_by              uuid references auth.users (id) on delete set null,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  constraint purchase_bills_totals_add_up check (
    total_paise = taxable_paise + cgst_paise + sgst_paise + igst_paise + cess_paise + round_off_paise
  )
);

-- A vendor's invoice number can be entered only once per financial year.
create unique index purchase_bills_vendor_invoice_uniq
  on public.purchase_bills (vendor_id, upper(vendor_invoice_number), financial_year)
  where status <> 'cancelled' and vendor_id is not null and vendor_invoice_number is not null;
create index purchase_bills_business_date_idx on public.purchase_bills (business_id, vendor_invoice_date desc);
create index purchase_bills_outlet_idx on public.purchase_bills (outlet_id);
create index purchase_bills_vendor_idx on public.purchase_bills (vendor_id);
create index purchase_bills_status_idx on public.purchase_bills (business_id, status);
create trigger purchase_bills_set_updated_at before update on public.purchase_bills
  for each row execute function public.set_updated_at();

create table public.purchase_bill_items (
  id                uuid primary key default gen_random_uuid(),
  purchase_bill_id  uuid not null references public.purchase_bills (id) on delete cascade,
  business_id       uuid not null references public.businesses (id) on delete cascade,
  line_no           integer not null default 1,
  product_id        uuid references public.products (id) on delete restrict,
  description       text not null,
  hsn_code          text,
  quantity          numeric(12,3) not null check (quantity > 0),
  unit_code         text not null default 'PCS' references public.units (code),
  rate_paise        bigint not null check (rate_paise >= 0),
  price_includes_tax boolean not null default false,
  discount_paise    bigint not null default 0 check (discount_paise >= 0),
  taxable_paise     bigint not null check (taxable_paise >= 0),
  gst_rate          numeric(5,2) not null default 0,
  cess_rate         numeric(5,2) not null default 0,
  cgst_paise        bigint not null default 0,
  sgst_paise        bigint not null default 0,
  igst_paise        bigint not null default 0,
  cess_paise        bigint not null default 0,
  total_paise       bigint not null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  constraint purchase_bill_items_total_adds_up check (
    total_paise = taxable_paise + cgst_paise + sgst_paise + igst_paise + cess_paise
  )
);

create index purchase_bill_items_bill_idx on public.purchase_bill_items (purchase_bill_id, line_no);
create index purchase_bill_items_product_idx on public.purchase_bill_items (product_id);
create index purchase_bill_items_business_idx on public.purchase_bill_items (business_id);

create table public.purchase_payments (
  id                uuid primary key default gen_random_uuid(),
  purchase_bill_id  uuid not null references public.purchase_bills (id) on delete cascade,
  business_id       uuid not null references public.businesses (id) on delete cascade,
  amount_paise      bigint not null check (amount_paise > 0),
  mode              text not null check (mode in ('cash', 'upi', 'card', 'bank_transfer', 'cheque')),
  paid_on           date not null default public.ist_today(),
  reference         text,
  created_by        uuid references auth.users (id) on delete set null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create index purchase_payments_bill_idx on public.purchase_payments (purchase_bill_id);
create index purchase_payments_business_date_idx on public.purchase_payments (business_id, paid_on desc);

-- Posted and cancelled purchase bills are locked. Only the payment roll-up,
-- the cancellation fields and notes may change afterwards.
create or replace function public.guard_purchase_bills()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_mutable text[] := array['status', 'cancelled_at', 'cancelled_by', 'cancel_reason',
                            'amount_paid_paise', 'payment_status', 'notes', 'updated_at'];
begin
  if tg_op = 'DELETE' then
    if old.status <> 'draft' and exists (select 1 from public.businesses b where b.id = old.business_id) then
      raise exception 'A % purchase bill cannot be deleted', old.status;
    end if;
    return old;
  end if;

  if old.status = 'cancelled' and (to_jsonb(new) - 'updated_at') is distinct from (to_jsonb(old) - 'updated_at') then
    raise exception 'A cancelled purchase bill cannot be changed';
  end if;
  if old.status = 'posted' then
    if (to_jsonb(new) - v_mutable) is distinct from (to_jsonb(old) - v_mutable) then
      raise exception 'A posted purchase bill cannot be edited. Cancel it and enter a new one.';
    end if;
    if new.status not in ('posted', 'cancelled') then
      raise exception 'A posted purchase bill cannot go back to draft';
    end if;
  end if;
  return new;
end;
$$;

create trigger purchase_bills_guard before update or delete on public.purchase_bills
  for each row execute function public.guard_purchase_bills();

create or replace function public.guard_purchase_bill_items()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_status text;
  v_bill uuid := case when tg_op = 'DELETE' then old.purchase_bill_id else new.purchase_bill_id end;
begin
  select status into v_status from public.purchase_bills where id = v_bill;
  if v_status is not null and v_status <> 'draft' then
    raise exception 'Items of a % purchase bill cannot be changed', v_status;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

create trigger purchase_bill_items_guard before insert or update or delete on public.purchase_bill_items
  for each row execute function public.guard_purchase_bill_items();

-- Keep amount_paid_paise and payment_status in step with the payments table.
create or replace function public.sync_purchase_payment_status()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_bill_id uuid := case when tg_op = 'DELETE' then old.purchase_bill_id else new.purchase_bill_id end;
  v_bill public.purchase_bills;
  v_paid bigint;
begin
  select * into v_bill from public.purchase_bills where id = v_bill_id for update;
  if not found then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if tg_op = 'INSERT' then
    if v_bill.status <> 'posted' then
      raise exception 'Payments can only be recorded against a posted purchase bill';
    end if;
    if new.business_id <> v_bill.business_id then
      raise exception 'Payment business does not match the bill';
    end if;
  end if;

  select coalesce(sum(amount_paise), 0) into v_paid from public.purchase_payments where purchase_bill_id = v_bill_id;
  if v_paid > v_bill.total_paise then
    raise exception 'Payments (%) cannot be more than the bill total (%)',
      to_char(v_paid / 100.0, 'FM999999999990.00'), to_char(v_bill.total_paise / 100.0, 'FM999999999990.00');
  end if;

  update public.purchase_bills
  set amount_paid_paise = v_paid,
      payment_status = case when v_paid <= 0 then 'unpaid'
                            when v_paid >= total_paise then 'paid'
                            else 'partial' end
  where id = v_bill_id;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

create trigger purchase_payments_sync after insert or delete on public.purchase_payments
  for each row execute function public.sync_purchase_payment_status();

create trigger purchase_payments_no_update before update on public.purchase_payments
  for each row execute function public.forbid_change();

-- Server-only. Creates or replaces a DRAFT purchase bill with its lines.
-- Totals are computed by the app's GST engine; this function re-checks that they add up.
create or replace function public.save_purchase_bill(p_actor uuid, p jsonb)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_business uuid := (p ->> 'business_id')::uuid;
  v_outlet uuid := (p ->> 'outlet_id')::uuid;
  v_bill_id uuid := nullif(p ->> 'id', '')::uuid;
  v_vendor uuid := nullif(p ->> 'vendor_id', '')::uuid;
  v_date date := nullif(p ->> 'vendor_invoice_date', '')::date;
  v_existing public.purchase_bills;
  v_item jsonb;
  v_line integer := 0;
  v_sum record;
begin
  if not public.has_perm_for(p_actor, v_business, 'purchases.create')
     or not public.can_access_outlet_for(p_actor, v_outlet) then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if not exists (select 1 from public.outlets where id = v_outlet and business_id = v_business) then
    raise exception 'Outlet does not belong to this business';
  end if;
  if v_vendor is not null and not exists (select 1 from public.vendors where id = v_vendor and business_id = v_business) then
    raise exception 'Vendor does not belong to this business';
  end if;
  if v_date is not null and v_date > public.ist_today() then
    raise exception 'The bill date cannot be in the future';
  end if;

  if v_bill_id is not null then
    select * into v_existing from public.purchase_bills where id = v_bill_id for update;
    if not found or v_existing.business_id <> v_business then
      raise exception 'Purchase bill not found';
    end if;
    if v_existing.status <> 'draft' then
      raise exception 'Only draft purchase bills can be edited';
    end if;

    update public.purchase_bills set
      outlet_id = v_outlet,
      vendor_id = v_vendor,
      vendor_invoice_number = nullif(trim(coalesce(p ->> 'vendor_invoice_number', '')), ''),
      vendor_invoice_date = v_date,
      financial_year = case when v_date is null then null else public.financial_year(v_date) end,
      place_of_supply_state = nullif(p ->> 'place_of_supply_state', ''),
      is_inter_state = coalesce((p ->> 'is_inter_state')::boolean, false),
      subtotal_paise = coalesce((p ->> 'subtotal_paise')::bigint, 0),
      discount_paise = coalesce((p ->> 'discount_paise')::bigint, 0),
      taxable_paise = coalesce((p ->> 'taxable_paise')::bigint, 0),
      cgst_paise = coalesce((p ->> 'cgst_paise')::bigint, 0),
      sgst_paise = coalesce((p ->> 'sgst_paise')::bigint, 0),
      igst_paise = coalesce((p ->> 'igst_paise')::bigint, 0),
      cess_paise = coalesce((p ->> 'cess_paise')::bigint, 0),
      round_off_paise = coalesce((p ->> 'round_off_paise')::bigint, 0),
      total_paise = coalesce((p ->> 'total_paise')::bigint, 0),
      attachment_paths = coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p -> 'attachment_paths', '[]'::jsonb)) x), '{}'),
      notes = nullif(trim(coalesce(p ->> 'notes', '')), '')
    where id = v_bill_id;

    delete from public.purchase_bill_items where purchase_bill_id = v_bill_id;
  else
    insert into public.purchase_bills (
      business_id, outlet_id, vendor_id, vendor_invoice_number, vendor_invoice_date, financial_year,
      place_of_supply_state, is_inter_state, status,
      subtotal_paise, discount_paise, taxable_paise, cgst_paise, sgst_paise, igst_paise, cess_paise,
      round_off_paise, total_paise, attachment_paths, notes, created_by
    ) values (
      v_business, v_outlet, v_vendor,
      nullif(trim(coalesce(p ->> 'vendor_invoice_number', '')), ''),
      v_date,
      case when v_date is null then null else public.financial_year(v_date) end,
      nullif(p ->> 'place_of_supply_state', ''),
      coalesce((p ->> 'is_inter_state')::boolean, false),
      'draft',
      coalesce((p ->> 'subtotal_paise')::bigint, 0),
      coalesce((p ->> 'discount_paise')::bigint, 0),
      coalesce((p ->> 'taxable_paise')::bigint, 0),
      coalesce((p ->> 'cgst_paise')::bigint, 0),
      coalesce((p ->> 'sgst_paise')::bigint, 0),
      coalesce((p ->> 'igst_paise')::bigint, 0),
      coalesce((p ->> 'cess_paise')::bigint, 0),
      coalesce((p ->> 'round_off_paise')::bigint, 0),
      coalesce((p ->> 'total_paise')::bigint, 0),
      coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p -> 'attachment_paths', '[]'::jsonb)) x), '{}'),
      nullif(trim(coalesce(p ->> 'notes', '')), ''),
      p_actor
    ) returning id into v_bill_id;
  end if;

  for v_item in select * from jsonb_array_elements(coalesce(p -> 'items', '[]'::jsonb)) loop
    v_line := v_line + 1;
    if nullif(v_item ->> 'product_id', '') is not null and not exists (
      select 1 from public.products where id = (v_item ->> 'product_id')::uuid and business_id = v_business
    ) then
      raise exception 'Line %: product does not belong to this business', v_line;
    end if;

    insert into public.purchase_bill_items (
      purchase_bill_id, business_id, line_no, product_id, description, hsn_code, quantity, unit_code,
      rate_paise, price_includes_tax, discount_paise, taxable_paise, gst_rate, cess_rate,
      cgst_paise, sgst_paise, igst_paise, cess_paise, total_paise
    ) values (
      v_bill_id, v_business, v_line,
      nullif(v_item ->> 'product_id', '')::uuid,
      v_item ->> 'description',
      nullif(v_item ->> 'hsn_code', ''),
      (v_item ->> 'quantity')::numeric,
      coalesce(nullif(v_item ->> 'unit_code', ''), 'PCS'),
      (v_item ->> 'rate_paise')::bigint,
      coalesce((v_item ->> 'price_includes_tax')::boolean, false),
      coalesce((v_item ->> 'discount_paise')::bigint, 0),
      (v_item ->> 'taxable_paise')::bigint,
      coalesce((v_item ->> 'gst_rate')::numeric, 0),
      coalesce((v_item ->> 'cess_rate')::numeric, 0),
      coalesce((v_item ->> 'cgst_paise')::bigint, 0),
      coalesce((v_item ->> 'sgst_paise')::bigint, 0),
      coalesce((v_item ->> 'igst_paise')::bigint, 0),
      coalesce((v_item ->> 'cess_paise')::bigint, 0),
      (v_item ->> 'total_paise')::bigint
    );
  end loop;

  select coalesce(sum(taxable_paise), 0) as taxable, coalesce(sum(cgst_paise), 0) as cgst,
         coalesce(sum(sgst_paise), 0) as sgst, coalesce(sum(igst_paise), 0) as igst,
         coalesce(sum(cess_paise), 0) as cess
  into v_sum from public.purchase_bill_items where purchase_bill_id = v_bill_id;

  if not exists (
    select 1 from public.purchase_bills b
    where b.id = v_bill_id and b.taxable_paise = v_sum.taxable and b.cgst_paise = v_sum.cgst
      and b.sgst_paise = v_sum.sgst and b.igst_paise = v_sum.igst and b.cess_paise = v_sum.cess
  ) then
    raise exception 'Purchase bill totals do not match its lines';
  end if;

  return v_bill_id;
end;
$$;

create or replace function public.post_purchase_bill(p_bill_id uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_bill public.purchase_bills;
  v_item record;
begin
  select * into v_bill from public.purchase_bills where id = p_bill_id for update;
  if not found
     or not public.has_perm(v_bill.business_id, 'purchases.post')
     or not public.can_access_outlet(v_bill.outlet_id) then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if v_bill.status <> 'draft' then
    raise exception 'This purchase bill is already %', v_bill.status;
  end if;
  if v_bill.vendor_id is null then
    raise exception 'Select a vendor before posting';
  end if;
  if v_bill.vendor_invoice_number is null or v_bill.vendor_invoice_date is null then
    raise exception 'Enter the vendor''s invoice number and date before posting';
  end if;
  if not exists (select 1 from public.purchase_bill_items where purchase_bill_id = p_bill_id) then
    raise exception 'Add at least one item before posting';
  end if;

  for v_item in
    select i.*, p.track_inventory
    from public.purchase_bill_items i
    join public.products p on p.id = i.product_id
    where i.purchase_bill_id = p_bill_id
    order by i.line_no
  loop
    if v_item.track_inventory then
      insert into public.stock_movements (business_id, outlet_id, product_id, quantity_delta, movement_type,
                                          source_table, source_id, note, created_by)
      values (v_bill.business_id, v_bill.outlet_id, v_item.product_id, v_item.quantity, 'purchase',
              'purchase_bills', p_bill_id, 'Purchase ' || v_bill.vendor_invoice_number, v_actor);
    end if;

    -- Remember the latest landed cost per unit (before tax).
    insert into public.product_costs as pc (product_id, business_id, purchase_price_paise, updated_by)
    values (v_item.product_id, v_bill.business_id, round(v_item.taxable_paise / v_item.quantity)::bigint, v_actor)
    on conflict (product_id) do update
      set purchase_price_paise = excluded.purchase_price_paise, updated_by = excluded.updated_by;
  end loop;

  update public.purchase_bills
  set status = 'posted', posted_at = now(), posted_by = v_actor
  where id = p_bill_id;

  perform public.write_audit(v_bill.business_id, v_actor, 'purchase.posted', 'purchase_bills', p_bill_id, null,
    jsonb_build_object('vendor_invoice_number', v_bill.vendor_invoice_number, 'total_paise', v_bill.total_paise));
end;
$$;

create or replace function public.cancel_purchase_bill(p_bill_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_bill public.purchase_bills;
  v_move record;
begin
  select * into v_bill from public.purchase_bills where id = p_bill_id for update;
  if not found or not public.can_access_outlet(v_bill.outlet_id) then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if v_bill.status = 'cancelled' then
    raise exception 'This purchase bill is already cancelled';
  end if;

  if v_bill.status = 'draft' then
    if not public.has_perm(v_bill.business_id, 'purchases.create') then
      raise exception 'Not allowed' using errcode = '42501';
    end if;
    delete from public.purchase_bills where id = p_bill_id;
    return;
  end if;

  if not public.has_perm(v_bill.business_id, 'purchases.post') then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_reason, ''))) = 0 then
    raise exception 'A reason is required to cancel a posted purchase bill';
  end if;
  if v_bill.amount_paid_paise > 0 then
    raise exception 'Remove the recorded payments before cancelling this bill';
  end if;

  for v_move in
    select product_id, sum(quantity_delta) as qty
    from public.stock_movements
    where source_table = 'purchase_bills' and source_id = p_bill_id and movement_type = 'purchase'
    group by product_id
  loop
    insert into public.stock_movements (business_id, outlet_id, product_id, quantity_delta, movement_type,
                                        source_table, source_id, note, created_by)
    values (v_bill.business_id, v_bill.outlet_id, v_move.product_id, -v_move.qty, 'purchase_cancel',
            'purchase_bills', p_bill_id, 'Purchase cancelled: ' || trim(p_reason), v_actor);
    perform public.assert_stock_available(v_bill.business_id, v_bill.outlet_id, v_move.product_id);
  end loop;

  update public.purchase_bills
  set status = 'cancelled', cancelled_at = now(), cancelled_by = v_actor, cancel_reason = trim(p_reason)
  where id = p_bill_id;

  perform public.write_audit(v_bill.business_id, v_actor, 'purchase.cancelled', 'purchase_bills', p_bill_id,
    jsonb_build_object('status', 'posted'),
    jsonb_build_object('status', 'cancelled', 'reason', trim(p_reason)));
end;
$$;

-- ── Row Level Security ──────────────────────────────────────────────────────

alter table public.stock_movements      enable row level security;
alter table public.stock_levels         enable row level security;
alter table public.purchase_bills       enable row level security;
alter table public.purchase_bill_items  enable row level security;
alter table public.purchase_payments    enable row level security;

-- Stock is read-only through the API; every write goes through an RPC.
create policy stock_movements_select on public.stock_movements for select to authenticated
  using (public.has_perm(business_id, 'inventory.view') and public.can_access_outlet(outlet_id));
create policy stock_levels_select on public.stock_levels for select to authenticated
  using (public.has_perm(business_id, 'inventory.view') and public.can_access_outlet(outlet_id));

create policy purchase_bills_select on public.purchase_bills for select to authenticated
  using (public.has_perm(business_id, 'purchases.view') and public.can_access_outlet(outlet_id));

create policy purchase_bill_items_select on public.purchase_bill_items for select to authenticated
  using (exists (select 1 from public.purchase_bills b where b.id = purchase_bill_id));

create policy purchase_payments_select on public.purchase_payments for select to authenticated
  using (exists (select 1 from public.purchase_bills b where b.id = purchase_bill_id));
create policy purchase_payments_insert on public.purchase_payments for insert to authenticated
  with check (
    public.has_perm(business_id, 'purchases.create')
    and exists (select 1 from public.purchase_bills b where b.id = purchase_bill_id and b.business_id = purchase_payments.business_id)
  );
create policy purchase_payments_delete on public.purchase_payments for delete to authenticated
  using (public.has_perm(business_id, 'purchases.post'));


-- ▶ 20261112000400_notifications.sql

-- ════════════════════════════════════════════════════════════════════════════
-- EkDum · 04 · Notification outbox (email + WhatsApp receipts)
-- ════════════════════════════════════════════════════════════════════════════
-- Transactional outbox: the invoice-posting RPC inserts rows here in the same
-- transaction as the invoice. /api/jobs/notifications claims and sends them.

create table public.notification_jobs (
  id                   uuid primary key default gen_random_uuid(),
  business_id          uuid not null references public.businesses (id) on delete cascade,
  channel              text not null check (channel in ('email', 'whatsapp')),
  template             text not null,
  recipient            text not null,
  payload              jsonb not null default '{}'::jsonb,
  related_table        text,
  related_id           uuid,
  status               text not null default 'queued' check (status in ('queued', 'sending', 'sent', 'failed')),
  attempts             integer not null default 0,
  next_attempt_at      timestamptz not null default now(),
  locked_at            timestamptz,
  last_error           text,
  provider_message_id  text,
  sent_at              timestamptz,
  created_by           uuid references auth.users (id) on delete set null,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

create index notification_jobs_due_idx on public.notification_jobs (next_attempt_at) where status = 'queued';
create index notification_jobs_business_idx on public.notification_jobs (business_id, created_at desc);
create index notification_jobs_related_idx on public.notification_jobs (related_table, related_id);
create index notification_jobs_failed_idx on public.notification_jobs (business_id) where status = 'failed';
create trigger notification_jobs_set_updated_at before update on public.notification_jobs
  for each row execute function public.set_updated_at();

-- Server-only. Claim up to p_limit due jobs. SKIP LOCKED lets several workers run safely.
-- Jobs stuck in 'sending' for over 10 minutes (a crashed worker) are picked up again.
create or replace function public.claim_notification_jobs(p_limit integer default 20)
returns setof public.notification_jobs
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  return query
  with due as (
    select j.id
    from public.notification_jobs j
    where (j.status = 'queued' and j.next_attempt_at <= now())
       or (j.status = 'sending' and j.locked_at < now() - interval '10 minutes')
    order by j.next_attempt_at
    limit greatest(1, least(p_limit, 100))
    for update skip locked
  )
  update public.notification_jobs j
  set status = 'sending', attempts = j.attempts + 1, locked_at = now()
  from due
  where j.id = due.id
  returning j.*;
end;
$$;

-- Server-only. Record the outcome of a send attempt.
-- Failure → retry with exponential backoff (2, 4, 8, 16 minutes); give up after 5 attempts.
create or replace function public.complete_notification_job(
  p_job_id uuid,
  p_success boolean,
  p_provider_message_id text default null,
  p_error text default null,
  p_permanent boolean default false
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_max_attempts constant integer := 5;
begin
  if p_success then
    update public.notification_jobs
    set status = 'sent', sent_at = now(), locked_at = null, last_error = null,
        provider_message_id = p_provider_message_id
    where id = p_job_id;
  else
    update public.notification_jobs
    set status = case when p_permanent or attempts >= v_max_attempts then 'failed' else 'queued' end,
        next_attempt_at = now() + (power(2, attempts) * interval '1 minute'),
        locked_at = null,
        last_error = left(coalesce(p_error, 'Unknown error'), 1000)
    where id = p_job_id;
  end if;
end;
$$;

-- Put a failed (or stuck) job back in the queue.
create or replace function public.retry_notification_job(p_job_id uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_job public.notification_jobs;
begin
  select * into v_job from public.notification_jobs where id = p_job_id for update;
  if not found
     or not (public.has_perm(v_job.business_id, 'sales.view_all') or public.has_perm(v_job.business_id, 'sales.create')) then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if v_job.status = 'sending' and v_job.locked_at > now() - interval '10 minutes' then
    raise exception 'This message is being sent right now';
  end if;
  update public.notification_jobs
  set status = 'queued', attempts = 0, next_attempt_at = now(), locked_at = null, last_error = null
  where id = p_job_id;
end;
$$;

alter table public.notification_jobs enable row level security;

create policy notification_jobs_select on public.notification_jobs for select to authenticated
  using (
    public.has_perm(business_id, 'sales.view_all')
    or (public.has_perm(business_id, 'sales.view_own') and created_by = (select auth.uid()))
  );


-- ▶ 20261112000500_sales.sql

-- ════════════════════════════════════════════════════════════════════════════
-- EkDum · 05 · POS devices, invoice series, sales invoices, credit notes
-- ════════════════════════════════════════════════════════════════════════════

-- ── POS devices and numbering series ────────────────────────────────────────

create table public.pos_devices (
  id               uuid primary key default gen_random_uuid(),
  business_id      uuid not null references public.businesses (id) on delete cascade,
  outlet_id        uuid not null references public.outlets (id) on delete restrict,
  name             text not null check (length(trim(name)) > 0),
  -- SHA-256 of the secret kept on the device. The secret itself is never stored.
  device_key_hash  text not null unique,
  last_seen_at     timestamptz,
  is_active        boolean not null default true,
  created_by       uuid references auth.users (id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

create index pos_devices_business_idx on public.pos_devices (business_id);
create index pos_devices_outlet_idx on public.pos_devices (outlet_id);
create trigger pos_devices_set_updated_at before update on public.pos_devices
  for each row execute function public.set_updated_at();

create table public.invoice_series (
  id              uuid primary key default gen_random_uuid(),
  business_id     uuid not null references public.businesses (id) on delete cascade,
  outlet_id       uuid not null references public.outlets (id) on delete restrict,
  -- Null → numbers are allocated by the server. Set → only that POS device issues them.
  pos_device_id   uuid references public.pos_devices (id) on delete restrict,
  document_type   text not null check (document_type in ('invoice', 'credit_note')),
  prefix          text not null check (prefix ~ '^[A-Z0-9]([A-Z0-9-]{0,2}[A-Z0-9])?$'),
  financial_year  text not null check (financial_year ~ '^[0-9]{4}$'),
  next_number     bigint not null default 1 check (next_number >= 1),
  is_active       boolean not null default true,
  created_by      uuid references auth.users (id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  -- A prefix identifies exactly one series per year, so two series can never issue the same number.
  unique (business_id, prefix, financial_year)
);

create unique index invoice_series_server_uniq
  on public.invoice_series (outlet_id, document_type, financial_year)
  where pos_device_id is null and is_active;
create unique index invoice_series_device_uniq
  on public.invoice_series (pos_device_id, document_type, financial_year)
  where pos_device_id is not null;
create index invoice_series_business_idx on public.invoice_series (business_id);
create trigger invoice_series_set_updated_at before update on public.invoice_series
  for each row execute function public.set_updated_at();

-- Numbers already issued can never be handed out again.
create or replace function public.guard_invoice_series()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if new.next_number < old.next_number then
    raise exception 'The next number of a series cannot be moved backwards';
  end if;
  if old.next_number > 1 and (new.prefix <> old.prefix or new.financial_year <> old.financial_year
      or new.document_type <> old.document_type) then
    raise exception 'A series that has already issued numbers cannot be changed. Create a new series instead.';
  end if;
  if new.business_id <> old.business_id then
    raise exception 'A series cannot be moved to another business';
  end if;
  return new;
end;
$$;

create trigger invoice_series_guard before update on public.invoice_series
  for each row execute function public.guard_invoice_series();

-- {PREFIX}/{FY}/{SEQ padded to 5}. Rule 46(b): at most 16 characters.
create or replace function public.format_document_number(p_prefix text, p_fy text, p_seq bigint)
returns text
language plpgsql
immutable
set search_path = public, pg_temp
as $$
declare
  -- lpad() truncates longer input, so pad to at least 5 digits, never fewer than the number has.
  v_number text := p_prefix || '/' || p_fy || '/' || lpad(p_seq::text, greatest(5, length(p_seq::text)), '0');
begin
  if length(v_number) > 16 then
    raise exception 'Invoice number % is longer than 16 characters. Start a new series with a shorter prefix.', v_number;
  end if;
  return v_number;
end;
$$;

-- Finds (and row-locks) the series for a financial year, rolling it over from
-- last year's series when the year changes.
create or replace function public.lock_series(
  p_business_id uuid,
  p_outlet_id uuid,
  p_device_id uuid,
  p_document_type text,
  p_fy text
)
returns public.invoice_series
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_series public.invoice_series;
  v_previous public.invoice_series;
begin
  select * into v_series from public.invoice_series s
  where s.business_id = p_business_id and s.outlet_id = p_outlet_id and s.document_type = p_document_type
    and s.financial_year = p_fy and s.is_active
    and s.pos_device_id is not distinct from p_device_id
  for update;
  if found then
    return v_series;
  end if;

  select * into v_previous from public.invoice_series s
  where s.business_id = p_business_id and s.outlet_id = p_outlet_id and s.document_type = p_document_type
    and s.is_active and s.pos_device_id is not distinct from p_device_id
  order by s.financial_year desc
  limit 1;
  if not found then
    raise exception 'No % number series is set up for this %',
      case when p_document_type = 'invoice' then 'invoice' else 'credit note' end,
      case when p_device_id is null then 'outlet' else 'POS device' end
      using hint = 'series_missing';
  end if;

  insert into public.invoice_series (business_id, outlet_id, pos_device_id, document_type, prefix,
                                     financial_year, next_number, is_active, created_by)
  values (p_business_id, p_outlet_id, p_device_id, p_document_type, v_previous.prefix, p_fy, 1, true, v_previous.created_by)
  on conflict do nothing;

  select * into v_series from public.invoice_series s
  where s.business_id = p_business_id and s.outlet_id = p_outlet_id and s.document_type = p_document_type
    and s.financial_year = p_fy and s.is_active
    and s.pos_device_id is not distinct from p_device_id
  for update;
  if not found then
    raise exception 'Could not start the % series for financial year %', v_previous.prefix, p_fy;
  end if;
  return v_series;
end;
$$;

-- Registers the calling browser/tablet as a POS device with its own invoice series.
create or replace function public.register_pos_device(
  p_outlet_id uuid,
  p_name text,
  p_prefix text,
  p_device_key_hash text
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_outlet public.outlets;
  v_device uuid;
  v_prefix text := upper(trim(p_prefix));
begin
  select * into v_outlet from public.outlets where id = p_outlet_id;
  if not found or not public.has_perm(v_outlet.business_id, 'settings.manage') then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if length(coalesce(p_device_key_hash, '')) < 32 then
    raise exception 'Invalid device key';
  end if;
  if exists (select 1 from public.invoice_series where business_id = v_outlet.business_id and prefix = v_prefix) then
    raise exception 'The prefix % is already used by another series', v_prefix;
  end if;

  insert into public.pos_devices (business_id, outlet_id, name, device_key_hash, created_by, last_seen_at)
  values (v_outlet.business_id, p_outlet_id, trim(p_name), p_device_key_hash, auth.uid(), now())
  returning id into v_device;

  insert into public.invoice_series (business_id, outlet_id, pos_device_id, document_type, prefix,
                                     financial_year, next_number, created_by)
  values (v_outlet.business_id, p_outlet_id, v_device, 'invoice', v_prefix,
          public.financial_year(public.ist_today()), 1, auth.uid());

  perform public.write_audit(v_outlet.business_id, auth.uid(), 'device.registered', 'pos_devices', v_device, null,
    jsonb_build_object('name', trim(p_name), 'prefix', v_prefix, 'outlet_id', p_outlet_id));
  return v_device;
end;
$$;

-- ── Sales invoices ──────────────────────────────────────────────────────────

create table public.sales_invoices (
  id                        uuid primary key default gen_random_uuid(),
  business_id               uuid not null references public.businesses (id) on delete cascade,
  outlet_id                 uuid not null references public.outlets (id) on delete restrict,
  series_id                 uuid not null references public.invoice_series (id) on delete restrict,
  pos_device_id             uuid references public.pos_devices (id) on delete restrict,
  invoice_number            text not null check (length(invoice_number) <= 16 and invoice_number ~ '^[A-Z0-9/-]+$'),
  financial_year            text not null,
  document_type             text not null check (document_type in ('tax_invoice', 'bill_of_supply', 'cash_memo')),
  invoice_date              date not null,
  -- Seller snapshot (the GSTIN under which this number is unique).
  seller_gstin              text,
  seller_state_code         text not null,
  -- Customer snapshot: a posted invoice never changes when the customer record does.
  customer_id               uuid references public.customers (id) on delete set null,
  customer_name             text,
  customer_phone            text,
  customer_email            text,
  customer_gstin            text,
  customer_address          text,
  customer_pincode          text,
  customer_state_code       text,
  supply_type               text not null default 'b2c' check (supply_type in ('b2b', 'b2c')),
  place_of_supply_state     text not null check (place_of_supply_state ~ '^[0-9]{2}$'),
  pos_override_reason       text,
  is_inter_state            boolean not null default false,
  reverse_charge            boolean not null default false,
  subtotal_paise            bigint not null check (subtotal_paise >= 0),
  discount_paise            bigint not null default 0 check (discount_paise >= 0),
  taxable_paise             bigint not null check (taxable_paise >= 0),
  cgst_paise                bigint not null default 0 check (cgst_paise >= 0),
  sgst_paise                bigint not null default 0 check (sgst_paise >= 0),
  igst_paise                bigint not null default 0 check (igst_paise >= 0),
  cess_paise                bigint not null default 0 check (cess_paise >= 0),
  round_off_paise           bigint not null default 0 check (round_off_paise between -99 and 99),
  total_paise               bigint not null check (total_paise >= 0),
  -- Outstanding "credit" (udhaar) still to be collected from the customer.
  amount_due_paise          bigint not null default 0 check (amount_due_paise >= 0),
  amount_in_words           text not null,
  notes                     text,
  status                    text not null default 'posted' check (status in ('posted', 'cancelled')),
  cancelled_at              timestamptz,
  cancelled_by              uuid references auth.users (id) on delete set null,
  cancel_reason             text,
  public_token              text not null unique default public.random_token(),
  public_token_revoked_at   timestamptz,
  -- Idempotency key generated on the client; makes offline sync safe to retry.
  client_uuid               uuid not null unique,
  source                    text not null check (source in ('pos_online', 'pos_offline', 'back_office')),
  created_by                uuid references auth.users (id) on delete set null,
  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now(),
  constraint sales_invoices_totals_add_up check (
    total_paise = taxable_paise + cgst_paise + sgst_paise + igst_paise + cess_paise + round_off_paise
  ),
  constraint sales_invoices_tax_split check (
    (is_inter_state and cgst_paise = 0 and sgst_paise = 0) or (not is_inter_state and igst_paise = 0)
  ),
  constraint sales_invoices_no_tax_unless_tax_invoice check (
    document_type = 'tax_invoice' or (cgst_paise = 0 and sgst_paise = 0 and igst_paise = 0 and cess_paise = 0)
  ),
  constraint sales_invoices_b2b_needs_gstin check (supply_type = 'b2c' or customer_gstin is not null)
);

-- Rule 46(b): the number is unique within a financial year for the supplier's GSTIN.
create unique index sales_invoices_number_uniq
  on public.sales_invoices (business_id, coalesce(seller_gstin, ''), financial_year, invoice_number);
create index sales_invoices_business_date_idx on public.sales_invoices (business_id, invoice_date desc, created_at desc);
create index sales_invoices_outlet_date_idx on public.sales_invoices (outlet_id, invoice_date desc);
create index sales_invoices_customer_idx on public.sales_invoices (customer_id);
create index sales_invoices_phone_idx on public.sales_invoices (business_id, customer_phone) where customer_phone is not null;
create index sales_invoices_created_by_idx on public.sales_invoices (created_by, invoice_date desc);
create index sales_invoices_series_idx on public.sales_invoices (series_id);
create index sales_invoices_device_idx on public.sales_invoices (pos_device_id);
create index sales_invoices_due_idx on public.sales_invoices (business_id) where amount_due_paise > 0;
create trigger sales_invoices_set_updated_at before update on public.sales_invoices
  for each row execute function public.set_updated_at();

create table public.sales_invoice_items (
  id                  uuid primary key default gen_random_uuid(),
  invoice_id          uuid not null references public.sales_invoices (id) on delete cascade,
  business_id         uuid not null references public.businesses (id) on delete cascade,
  line_no             integer not null,
  product_id          uuid references public.products (id) on delete restrict,
  description         text not null,
  hsn_code            text,
  quantity            numeric(12,3) not null check (quantity > 0),
  unit_code           text not null default 'PCS',
  unit_price_paise    bigint not null check (unit_price_paise >= 0),
  price_includes_tax  boolean not null default true,
  discount_paise      bigint not null default 0 check (discount_paise >= 0),
  taxable_paise       bigint not null check (taxable_paise >= 0),
  gst_rate            numeric(5,2) not null default 0,
  cess_rate           numeric(5,2) not null default 0,
  cgst_paise          bigint not null default 0 check (cgst_paise >= 0),
  sgst_paise          bigint not null default 0 check (sgst_paise >= 0),
  igst_paise          bigint not null default 0 check (igst_paise >= 0),
  cess_paise          bigint not null default 0 check (cess_paise >= 0),
  total_paise         bigint not null check (total_paise >= 0),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (invoice_id, line_no),
  constraint sales_invoice_items_total_adds_up check (
    total_paise = taxable_paise + cgst_paise + sgst_paise + igst_paise + cess_paise
  )
);

create index sales_invoice_items_product_idx on public.sales_invoice_items (product_id);
create index sales_invoice_items_business_idx on public.sales_invoice_items (business_id);

create table public.sales_payments (
  id             uuid primary key default gen_random_uuid(),
  invoice_id     uuid not null references public.sales_invoices (id) on delete cascade,
  business_id    uuid not null references public.businesses (id) on delete cascade,
  mode           text not null check (mode in ('cash', 'upi', 'card', 'bank_transfer', 'credit')),
  amount_paise   bigint not null check (amount_paise > 0),
  reference      text,
  -- False: taken when the bill was made. True: collected later against a credit sale.
  is_collection  boolean not null default false,
  received_on    date not null default public.ist_today(),
  created_by     uuid references auth.users (id) on delete set null,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint sales_payments_collection_not_credit check (not (is_collection and mode = 'credit'))
);

create index sales_payments_invoice_idx on public.sales_payments (invoice_id);
create index sales_payments_business_date_idx on public.sales_payments (business_id, received_on desc);

-- ── Credit notes ────────────────────────────────────────────────────────────

create table public.credit_notes (
  id                         uuid primary key default gen_random_uuid(),
  business_id                uuid not null references public.businesses (id) on delete cascade,
  outlet_id                  uuid not null references public.outlets (id) on delete restrict,
  invoice_id                 uuid not null references public.sales_invoices (id) on delete restrict,
  series_id                  uuid not null references public.invoice_series (id) on delete restrict,
  credit_note_number         text not null check (length(credit_note_number) <= 16),
  financial_year             text not null,
  credit_note_date           date not null,
  seller_gstin               text,
  reason                     text not null check (length(trim(reason)) > 0),
  restock                    boolean not null default false,
  is_inter_state             boolean not null default false,
  taxable_paise              bigint not null check (taxable_paise >= 0),
  cgst_paise                 bigint not null default 0,
  sgst_paise                 bigint not null default 0,
  igst_paise                 bigint not null default 0,
  cess_paise                 bigint not null default 0,
  round_off_paise            bigint not null default 0,
  total_paise                bigint not null check (total_paise >= 0),
  -- How the customer got the value back.
  adjusted_against_due_paise bigint not null default 0 check (adjusted_against_due_paise >= 0),
  refund_paise               bigint not null default 0 check (refund_paise >= 0),
  refund_mode                text check (refund_mode is null or refund_mode in ('cash', 'upi', 'card', 'bank_transfer')),
  created_by                 uuid references auth.users (id) on delete set null,
  created_at                 timestamptz not null default now(),
  updated_at                 timestamptz not null default now(),
  constraint credit_notes_totals_add_up check (
    total_paise = taxable_paise + cgst_paise + sgst_paise + igst_paise + cess_paise + round_off_paise
  ),
  constraint credit_notes_settlement_adds_up check (total_paise = adjusted_against_due_paise + refund_paise)
);

create unique index credit_notes_number_uniq
  on public.credit_notes (business_id, coalesce(seller_gstin, ''), financial_year, credit_note_number);
create index credit_notes_invoice_idx on public.credit_notes (invoice_id);
create index credit_notes_business_date_idx on public.credit_notes (business_id, credit_note_date desc);
create index credit_notes_outlet_idx on public.credit_notes (outlet_id);
create index credit_notes_series_idx on public.credit_notes (series_id);

create table public.credit_note_items (
  id                uuid primary key default gen_random_uuid(),
  credit_note_id    uuid not null references public.credit_notes (id) on delete cascade,
  business_id       uuid not null references public.businesses (id) on delete cascade,
  invoice_item_id   uuid not null references public.sales_invoice_items (id) on delete restrict,
  line_no           integer not null,
  product_id        uuid references public.products (id) on delete restrict,
  description       text not null,
  hsn_code          text,
  quantity          numeric(12,3) not null check (quantity > 0),
  unit_code         text not null,
  unit_price_paise  bigint not null,
  taxable_paise     bigint not null check (taxable_paise >= 0),
  gst_rate          numeric(5,2) not null default 0,
  cess_rate         numeric(5,2) not null default 0,
  cgst_paise        bigint not null default 0,
  sgst_paise        bigint not null default 0,
  igst_paise        bigint not null default 0,
  cess_paise        bigint not null default 0,
  total_paise       bigint not null check (total_paise >= 0),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create index credit_note_items_note_idx on public.credit_note_items (credit_note_id, line_no);
create index credit_note_items_invoice_item_idx on public.credit_note_items (invoice_item_id);
create index credit_note_items_product_idx on public.credit_note_items (product_id);
create index credit_note_items_business_idx on public.credit_note_items (business_id);

-- ── Immutability of posted financial documents ──────────────────────────────

create or replace function public.guard_sales_invoices()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_mutable text[] := array['status', 'cancelled_at', 'cancelled_by', 'cancel_reason',
                            'public_token_revoked_at', 'amount_due_paise', 'updated_at'];
begin
  if tg_op = 'DELETE' then
    if exists (select 1 from public.businesses b where b.id = old.business_id) then
      raise exception 'Invoices cannot be deleted. Cancel the invoice or issue a credit note.';
    end if;
    return old;
  end if;

  -- Deleting a customer unlinks their bills (FK on delete set null). The bill keeps
  -- its own snapshot of the customer's details, so nothing printed changes.
  if new.customer_id is null and old.customer_id is not null then
    old.customer_id := null;
  end if;
  if (to_jsonb(new) - v_mutable) is distinct from (to_jsonb(old) - v_mutable) then
    raise exception 'A posted invoice cannot be edited. Cancel it or issue a credit note.';
  end if;
  if old.status = 'cancelled' and new.status <> 'cancelled' then
    raise exception 'A cancelled invoice cannot be restored';
  end if;
  return new;
end;
$$;

create trigger sales_invoices_guard before update or delete on public.sales_invoices
  for each row execute function public.guard_sales_invoices();

create trigger sales_invoice_items_immutable before update or delete on public.sales_invoice_items
  for each row execute function public.forbid_change();
create trigger sales_payments_immutable before update or delete on public.sales_payments
  for each row execute function public.forbid_change();
create trigger credit_notes_immutable before update or delete on public.credit_notes
  for each row execute function public.forbid_change();
create trigger credit_note_items_immutable before update or delete on public.credit_note_items
  for each row execute function public.forbid_change();

-- ── Notifications for an invoice ────────────────────────────────────────────

create or replace function public.queue_invoice_notification(
  p_invoice_id uuid,
  p_channel text,
  p_recipient text,
  p_actor uuid
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_inv public.sales_invoices;
  v_job uuid;
begin
  select * into v_inv from public.sales_invoices where id = p_invoice_id;
  if not found or length(trim(coalesce(p_recipient, ''))) = 0 then
    return null;
  end if;

  insert into public.notification_jobs (business_id, channel, template, recipient, payload,
                                        related_table, related_id, created_by)
  values (
    v_inv.business_id, p_channel, 'invoice_receipt', trim(p_recipient),
    jsonb_build_object(
      'invoice_id', v_inv.id,
      'invoice_number', v_inv.invoice_number,
      'customer_name', v_inv.customer_name,
      'total_paise', v_inv.total_paise
    ),
    'sales_invoices', v_inv.id, p_actor
  ) returning id into v_job;
  return v_job;
end;
$$;

-- Manual "send receipt" from the invoice page.
create or replace function public.send_invoice_notification(p_invoice_id uuid, p_channel text, p_recipient text default null)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_inv public.sales_invoices;
  v_recipient text;
  v_opted_in boolean;
begin
  select * into v_inv from public.sales_invoices where id = p_invoice_id;
  if not found
     or not public.can_access_outlet(v_inv.outlet_id)
     or not (public.has_perm(v_inv.business_id, 'sales.view_all')
             or (public.has_perm(v_inv.business_id, 'sales.view_own') and v_inv.created_by = auth.uid())) then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if p_channel not in ('email', 'whatsapp') then
    raise exception 'Unknown channel';
  end if;
  if v_inv.status = 'cancelled' then
    raise exception 'This invoice is cancelled';
  end if;

  if p_channel = 'email' then
    v_recipient := coalesce(nullif(trim(coalesce(p_recipient, '')), ''), v_inv.customer_email);
    if v_recipient is null or position('@' in v_recipient) < 2 then
      raise exception 'Enter an email address to send the receipt to';
    end if;
  else
    -- WhatsApp is only ever sent to the customer on the bill, and only with consent.
    v_recipient := v_inv.customer_phone;
    select whatsapp_opt_in into v_opted_in from public.customers where id = v_inv.customer_id;
    if v_recipient is null then
      raise exception 'This bill has no customer phone number';
    end if;
    if not coalesce(v_opted_in, false) then
      raise exception 'The customer has not opted in to WhatsApp messages';
    end if;
  end if;

  return public.queue_invoice_notification(p_invoice_id, p_channel, v_recipient, auth.uid());
end;
$$;

-- ── Posting an invoice ──────────────────────────────────────────────────────
-- Server-only (service role). The app server recomputes every amount with the
-- shared GST engine before calling this; the function then, in ONE transaction:
-- checks permissions → allocates/validates the number → inserts invoice, lines
-- and payments → writes stock movements → queues notifications → writes audit rows.

create or replace function public.post_sales_invoice(p_actor uuid, p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_business_id uuid := (p ->> 'business_id')::uuid;
  v_outlet_id uuid := (p ->> 'outlet_id')::uuid;
  v_client_uuid uuid := (p ->> 'client_uuid')::uuid;
  v_source text := p ->> 'source';
  v_device_id uuid := nullif(p ->> 'device_id', '')::uuid;
  v_offline boolean := (p ->> 'source') = 'pos_offline';
  v_doc_type text := p ->> 'document_type';
  v_supply_type text := coalesce(p ->> 'supply_type', 'b2c');
  v_customer_id uuid := nullif(p ->> 'customer_id', '')::uuid;
  v_cust jsonb := coalesce(p -> 'customer', '{}'::jsonb);
  v_pos_state text := p ->> 'place_of_supply_state';
  v_inter boolean := coalesce((p ->> 'is_inter_state')::boolean, false);
  v_subtotal bigint := (p ->> 'subtotal_paise')::bigint;
  v_discount bigint := coalesce((p ->> 'discount_paise')::bigint, 0);
  v_taxable bigint := (p ->> 'taxable_paise')::bigint;
  v_cgst bigint := coalesce((p ->> 'cgst_paise')::bigint, 0);
  v_sgst bigint := coalesce((p ->> 'sgst_paise')::bigint, 0);
  v_igst bigint := coalesce((p ->> 'igst_paise')::bigint, 0);
  v_cess bigint := coalesce((p ->> 'cess_paise')::bigint, 0);
  v_round_off bigint := coalesce((p ->> 'round_off_paise')::bigint, 0);
  v_total bigint := (p ->> 'total_paise')::bigint;
  v_today date := public.ist_today();
  v_date date;
  v_fy text;
  v_business public.businesses;
  v_outlet public.outlets;
  v_device public.pos_devices;
  v_customer public.customers;
  v_series public.invoice_series;
  v_existing public.sales_invoices;
  v_seller_gstin text;
  v_seller_state text;
  v_number text;
  v_seq bigint;
  v_invoice_id uuid;
  v_item jsonb;
  v_pay jsonb;
  v_line integer := 0;
  v_product public.products;
  v_sum_taxable bigint := 0;
  v_sum_cgst bigint := 0;
  v_sum_sgst bigint := 0;
  v_sum_igst bigint := 0;
  v_sum_cess bigint := 0;
  v_sum_discount bigint := 0;
  v_paid bigint := 0;
  v_due bigint := 0;
  v_max_discount numeric;
  v_discount_pct numeric;
  v_warnings jsonb := '[]'::jsonb;
  v_can_override boolean;
  v_item_count integer;
begin
  -- 1. Idempotency: a retried request returns the invoice that was already posted.
  select * into v_existing from public.sales_invoices where client_uuid = v_client_uuid;
  if found then
    if v_existing.business_id <> v_business_id then
      raise exception 'Duplicate request id';
    end if;
    return jsonb_build_object('invoice_id', v_existing.id, 'invoice_number', v_existing.invoice_number,
                              'public_token', v_existing.public_token, 'duplicate', true, 'warnings', '[]'::jsonb);
  end if;

  -- 2. Who and where.
  select * into v_business from public.businesses where id = v_business_id;
  select * into v_outlet from public.outlets where id = v_outlet_id;
  if v_business.id is null or v_outlet.id is null or v_outlet.business_id <> v_business_id then
    raise exception 'Outlet not found';
  end if;
  if not public.has_perm_for(p_actor, v_business_id, 'sales.create')
     or not public.can_access_outlet_for(p_actor, v_outlet_id) then
    raise exception 'You are not allowed to create bills for this outlet' using errcode = '42501';
  end if;
  if not v_outlet.is_active then
    raise exception 'This outlet is not active';
  end if;
  if v_source not in ('pos_online', 'pos_offline', 'back_office') then
    raise exception 'Unknown bill source';
  end if;

  v_item_count := jsonb_array_length(coalesce(p -> 'items', '[]'::jsonb));
  if v_item_count = 0 then
    raise exception 'A bill needs at least one item';
  end if;

  -- 3. Date and financial year. Online bills are always dated today (IST);
  --    offline bills keep the date they were printed with.
  v_date := case when v_offline then coalesce(nullif(p ->> 'invoice_date', '')::date, v_today) else v_today end;
  if v_date > v_today then
    raise exception 'The bill date cannot be in the future';
  end if;
  v_fy := public.financial_year(v_date);

  -- 4. Seller identity and document type.
  v_seller_gstin := case when v_business.gst_scheme = 'unregistered' then null
                         else coalesce(v_outlet.gstin, v_business.gstin) end;
  v_seller_state := coalesce(left(v_seller_gstin, 2), v_outlet.state_code);

  if (v_business.gst_scheme = 'composition' and v_doc_type <> 'bill_of_supply')
     or (v_business.gst_scheme = 'unregistered' and v_doc_type <> 'cash_memo')
     or (v_business.gst_scheme = 'regular' and v_doc_type not in ('tax_invoice', 'bill_of_supply')) then
    raise exception 'Document type % is not valid for a % business', v_doc_type, v_business.gst_scheme;
  end if;
  if v_inter is distinct from (v_seller_state <> v_pos_state) then
    raise exception 'Inter-state flag does not match the place of supply';
  end if;

  -- 5. Customer.
  if v_customer_id is not null then
    select * into v_customer from public.customers where id = v_customer_id and business_id = v_business_id;
    if not found then
      raise exception 'Customer not found';
    end if;
  end if;
  if v_supply_type = 'b2b' and nullif(v_cust ->> 'gstin', '') is null then
    raise exception 'A B2B bill needs the customer''s GSTIN';
  end if;

  -- 6. Totals must be internally consistent (the CHECK constraints repeat this).
  for v_item in select * from jsonb_array_elements(p -> 'items') loop
    v_sum_taxable := v_sum_taxable + (v_item ->> 'taxable_paise')::bigint;
    v_sum_cgst := v_sum_cgst + coalesce((v_item ->> 'cgst_paise')::bigint, 0);
    v_sum_sgst := v_sum_sgst + coalesce((v_item ->> 'sgst_paise')::bigint, 0);
    v_sum_igst := v_sum_igst + coalesce((v_item ->> 'igst_paise')::bigint, 0);
    v_sum_cess := v_sum_cess + coalesce((v_item ->> 'cess_paise')::bigint, 0);
    v_sum_discount := v_sum_discount + coalesce((v_item ->> 'discount_paise')::bigint, 0);
  end loop;
  if v_sum_taxable <> v_taxable or v_sum_cgst <> v_cgst or v_sum_sgst <> v_sgst
     or v_sum_igst <> v_igst or v_sum_cess <> v_cess or v_sum_discount <> v_discount then
    raise exception 'Bill totals do not match its lines';
  end if;

  -- 7. Discount limit for the cashier's role.
  if v_discount > 0 then
    v_max_discount := public.max_discount_for(p_actor, v_business_id);
    v_discount_pct := case when v_subtotal > 0 then round(v_discount * 100.0 / v_subtotal, 2) else 0 end;
    if v_discount_pct > v_max_discount then
      if v_offline then
        -- The customer already has this bill, so it is accepted and flagged.
        v_warnings := v_warnings || jsonb_build_object('code', 'discount_over_limit',
          'message', format('Discount %s%% is above the role limit of %s%%', v_discount_pct, v_max_discount));
        perform public.write_audit(v_business_id, p_actor, 'sale.offline_discount_over_limit', 'sales_invoices', null,
          null, jsonb_build_object('client_uuid', v_client_uuid, 'discount_percent', v_discount_pct, 'limit', v_max_discount));
      else
        raise exception '%', format('Discount of %s%% is above your limit of %s%%', v_discount_pct, v_max_discount)
          using hint = 'discount_over_limit';
      end if;
    end if;
  end if;

  -- 8. Payments: must add up to the bill total; "credit" needs a customer.
  for v_pay in select * from jsonb_array_elements(coalesce(p -> 'payments', '[]'::jsonb)) loop
    if (v_pay ->> 'amount_paise')::bigint <= 0 then
      raise exception 'Payment amounts must be more than zero';
    end if;
    v_paid := v_paid + (v_pay ->> 'amount_paise')::bigint;
    if v_pay ->> 'mode' = 'credit' then
      v_due := v_due + (v_pay ->> 'amount_paise')::bigint;
    end if;
  end loop;
  if v_paid <> v_total then
    raise exception 'Payments (%) do not add up to the bill total (%)',
      to_char(v_paid / 100.0, 'FM999999999990.00'), to_char(v_total / 100.0, 'FM999999999990.00');
  end if;
  if v_due > 0 and v_customer_id is null then
    raise exception 'Select a customer to give credit';
  end if;

  -- 9. Number. Device series: the device issued the number and the server checks it.
  --    Server series: allocate the next number under a row lock (no gaps, no duplicates).
  if v_device_id is not null then
    select * into v_device from public.pos_devices where id = v_device_id for update;
    if not found or v_device.business_id <> v_business_id or v_device.outlet_id <> v_outlet_id then
      raise exception 'This POS device is not registered for this outlet' using hint = 'device_invalid';
    end if;
    if not v_device.is_active then
      raise exception 'This POS device has been deactivated' using hint = 'device_inactive';
    end if;

    v_series := public.lock_series(v_business_id, v_outlet_id, v_device_id, 'invoice', v_fy);
    v_number := p ->> 'invoice_number';
    if v_number is null or v_number !~ ('^' || v_series.prefix || '/' || v_fy || '/[0-9]{5,}$') or length(v_number) > 16 then
      raise exception 'Bill number % does not belong to this device''s series (%/%)',
        coalesce(v_number, '(none)'), v_series.prefix, v_fy using hint = 'number_invalid';
    end if;
    v_seq := split_part(v_number, '/', 3)::bigint;
    if v_seq < 1 then
      raise exception 'Bill number % is not valid', v_number using hint = 'number_invalid';
    end if;
    if exists (
      select 1 from public.sales_invoices i
      where i.business_id = v_business_id and coalesce(i.seller_gstin, '') = coalesce(v_seller_gstin, '')
        and i.financial_year = v_fy and i.invoice_number = v_number
    ) then
      raise exception 'Bill number % has already been used', v_number using hint = 'number_conflict';
    end if;

    if v_seq > v_series.next_number then
      v_warnings := v_warnings || jsonb_build_object('code', 'series_gap',
        'message', format('Numbers %s to %s of series %s are missing', v_series.next_number, v_seq - 1, v_series.prefix));
      perform public.write_audit(v_business_id, p_actor, 'series.gap', 'invoice_series', v_series.id, null,
        jsonb_build_object('expected', v_series.next_number, 'received', v_seq, 'invoice_number', v_number,
                           'device_id', v_device_id));
    end if;
    if v_seq >= v_series.next_number then
      update public.invoice_series set next_number = v_seq + 1 where id = v_series.id;
    end if;
    update public.pos_devices set last_seen_at = now() where id = v_device_id;
  else
    v_series := public.lock_series(v_business_id, v_outlet_id, null, 'invoice', v_fy);
    v_seq := v_series.next_number;
    v_number := public.format_document_number(v_series.prefix, v_fy, v_seq);
    update public.invoice_series set next_number = v_seq + 1 where id = v_series.id;
  end if;

  -- 10. Invoice header.
  insert into public.sales_invoices (
    business_id, outlet_id, series_id, pos_device_id, invoice_number, financial_year, document_type, invoice_date,
    seller_gstin, seller_state_code,
    customer_id, customer_name, customer_phone, customer_email, customer_gstin, customer_address,
    customer_pincode, customer_state_code,
    supply_type, place_of_supply_state, pos_override_reason, is_inter_state, reverse_charge,
    subtotal_paise, discount_paise, taxable_paise, cgst_paise, sgst_paise, igst_paise, cess_paise,
    round_off_paise, total_paise, amount_due_paise, amount_in_words, notes,
    public_token, client_uuid, source, created_by
  ) values (
    v_business_id, v_outlet_id, v_series.id, v_device_id, v_number, v_fy, v_doc_type, v_date,
    v_seller_gstin, v_seller_state,
    v_customer_id,
    nullif(trim(coalesce(v_cust ->> 'name', '')), ''),
    nullif(v_cust ->> 'phone', ''),
    nullif(lower(trim(coalesce(v_cust ->> 'email', ''))), ''),
    nullif(upper(v_cust ->> 'gstin'), ''),
    nullif(trim(coalesce(v_cust ->> 'address', '')), ''),
    nullif(v_cust ->> 'pincode', ''),
    nullif(v_cust ->> 'state_code', ''),
    v_supply_type, v_pos_state, nullif(trim(coalesce(p ->> 'pos_override_reason', '')), ''), v_inter,
    coalesce((p ->> 'reverse_charge')::boolean, false),
    v_subtotal, v_discount, v_taxable, v_cgst, v_sgst, v_igst, v_cess,
    v_round_off, v_total, v_due, p ->> 'amount_in_words', nullif(trim(coalesce(p ->> 'notes', '')), ''),
    coalesce(nullif(p ->> 'public_token', ''), public.random_token()), v_client_uuid, v_source, p_actor
  ) returning id into v_invoice_id;

  -- 11. Lines + stock.
  v_can_override := public.has_perm_for(p_actor, v_business_id, 'sales.price_override');
  for v_item in select * from jsonb_array_elements(p -> 'items') loop
    v_line := v_line + 1;
    v_product := null;

    if nullif(v_item ->> 'product_id', '') is not null then
      select * into v_product from public.products
      where id = (v_item ->> 'product_id')::uuid and business_id = v_business_id;
      if not found then
        raise exception 'Line %: product not found', v_line;
      end if;

      if (v_item ->> 'unit_price_paise')::bigint <> v_product.sale_price_paise then
        if v_offline then
          -- Offline prices are what the customer paid; accept and log the difference.
          perform public.write_audit(v_business_id, p_actor, 'sale.offline_price_mismatch', 'sales_invoices', v_invoice_id,
            jsonb_build_object('product_id', v_product.id, 'price_paise', v_product.sale_price_paise),
            jsonb_build_object('price_paise', (v_item ->> 'unit_price_paise')::bigint, 'invoice_number', v_number,
                               'product', v_product.name));
        elsif not v_can_override then
          raise exception 'Line %: you are not allowed to change the price of "%"', v_line, v_product.name
            using hint = 'price_override_denied';
        else
          perform public.write_audit(v_business_id, p_actor, 'sale.price_override', 'sales_invoices', v_invoice_id,
            jsonb_build_object('product_id', v_product.id, 'price_paise', v_product.sale_price_paise),
            jsonb_build_object('price_paise', (v_item ->> 'unit_price_paise')::bigint, 'invoice_number', v_number,
                               'product', v_product.name));
        end if;
      end if;
    end if;

    insert into public.sales_invoice_items (
      invoice_id, business_id, line_no, product_id, description, hsn_code, quantity, unit_code,
      unit_price_paise, price_includes_tax, discount_paise, taxable_paise, gst_rate, cess_rate,
      cgst_paise, sgst_paise, igst_paise, cess_paise, total_paise
    ) values (
      v_invoice_id, v_business_id, v_line, v_product.id,
      coalesce(nullif(trim(coalesce(v_item ->> 'description', '')), ''), v_product.name),
      nullif(v_item ->> 'hsn_code', ''),
      (v_item ->> 'quantity')::numeric,
      coalesce(nullif(v_item ->> 'unit_code', ''), 'PCS'),
      (v_item ->> 'unit_price_paise')::bigint,
      coalesce((v_item ->> 'price_includes_tax')::boolean, true),
      coalesce((v_item ->> 'discount_paise')::bigint, 0),
      (v_item ->> 'taxable_paise')::bigint,
      coalesce((v_item ->> 'gst_rate')::numeric, 0),
      coalesce((v_item ->> 'cess_rate')::numeric, 0),
      coalesce((v_item ->> 'cgst_paise')::bigint, 0),
      coalesce((v_item ->> 'sgst_paise')::bigint, 0),
      coalesce((v_item ->> 'igst_paise')::bigint, 0),
      coalesce((v_item ->> 'cess_paise')::bigint, 0),
      (v_item ->> 'total_paise')::bigint
    );

    if v_product.id is not null and v_product.track_inventory then
      insert into public.stock_movements (business_id, outlet_id, product_id, quantity_delta, movement_type,
                                          source_table, source_id, note, created_by)
      values (v_business_id, v_outlet_id, v_product.id, -((v_item ->> 'quantity')::numeric), 'sale',
              'sales_invoices', v_invoice_id, 'Sale ' || v_number, p_actor);

      if v_offline then
        if (select quantity < 0 from public.stock_levels where product_id = v_product.id and outlet_id = v_outlet_id)
           and not v_business.allow_negative_stock then
          v_warnings := v_warnings || jsonb_build_object('code', 'negative_stock',
            'message', format('Stock of "%s" went below zero', v_product.name));
        end if;
      else
        perform public.assert_stock_available(v_business_id, v_outlet_id, v_product.id);
      end if;
    end if;
  end loop;

  -- 12. Payments.
  insert into public.sales_payments (invoice_id, business_id, mode, amount_paise, reference, received_on, created_by)
  select v_invoice_id, v_business_id, x ->> 'mode', (x ->> 'amount_paise')::bigint,
         nullif(trim(coalesce(x ->> 'reference', '')), ''), v_date, p_actor
  from jsonb_array_elements(coalesce(p -> 'payments', '[]'::jsonb)) x;

  -- 13. WhatsApp consent captured at the counter.
  if v_customer_id is not null and coalesce((p ->> 'whatsapp_opt_in')::boolean, false) and not v_customer.whatsapp_opt_in then
    update public.customers set whatsapp_opt_in = true where id = v_customer_id;
    v_customer.whatsapp_opt_in := true;
  end if;

  -- 14. Receipts (transactional outbox).
  if coalesce((p -> 'notify' ->> 'email')::boolean, false) and v_business.notify_email_enabled
     and nullif(v_cust ->> 'email', '') is not null then
    perform public.queue_invoice_notification(v_invoice_id, 'email', lower(trim(v_cust ->> 'email')), p_actor);
  end if;
  if coalesce((p -> 'notify' ->> 'whatsapp')::boolean, false) and v_business.notify_whatsapp_enabled
     and v_customer_id is not null and v_customer.whatsapp_opt_in and nullif(v_cust ->> 'phone', '') is not null then
    perform public.queue_invoice_notification(v_invoice_id, 'whatsapp', v_cust ->> 'phone', p_actor);
  end if;

  -- 15. Audit: place-of-supply override.
  if nullif(trim(coalesce(p ->> 'pos_override_reason', '')), '') is not null then
    perform public.write_audit(v_business_id, p_actor, 'sale.place_of_supply_override', 'sales_invoices', v_invoice_id,
      null, jsonb_build_object('place_of_supply_state', v_pos_state, 'reason', p ->> 'pos_override_reason',
                               'invoice_number', v_number));
  end if;

  return jsonb_build_object('invoice_id', v_invoice_id, 'invoice_number', v_number,
                            'public_token', (select public_token from public.sales_invoices where id = v_invoice_id),
                            'duplicate', false, 'warnings', v_warnings);
end;
$$;

-- ── Cancellation ────────────────────────────────────────────────────────────

create or replace function public.cancel_sales_invoice(p_invoice_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_inv public.sales_invoices;
  v_window integer;
  v_move record;
begin
  select * into v_inv from public.sales_invoices where id = p_invoice_id for update;
  if not found
     or not public.has_perm(v_inv.business_id, 'sales.cancel')
     or not public.can_access_outlet(v_inv.outlet_id) then
    raise exception 'You are not allowed to cancel bills' using errcode = '42501';
  end if;
  if v_inv.status = 'cancelled' then
    raise exception 'This bill is already cancelled';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A reason is required to cancel a bill';
  end if;
  if exists (select 1 from public.credit_notes where invoice_id = p_invoice_id) then
    raise exception 'This bill has a credit note against it and cannot be cancelled';
  end if;

  select cancel_window_days into v_window from public.businesses where id = v_inv.business_id;
  if v_window is not null and public.ist_today() - v_inv.invoice_date > v_window then
    raise exception 'This bill is too old to cancel (%). Issue a credit note instead.',
      case when v_window = 0 then 'only same-day cancellation is allowed'
           else format('the limit is %s days', v_window) end
      using hint = 'cancel_window_passed';
  end if;

  -- Put the stock back exactly as it went out.
  for v_move in
    select product_id, sum(quantity_delta) as qty
    from public.stock_movements
    where source_table = 'sales_invoices' and source_id = p_invoice_id and movement_type = 'sale'
    group by product_id
  loop
    insert into public.stock_movements (business_id, outlet_id, product_id, quantity_delta, movement_type,
                                        source_table, source_id, note, created_by)
    values (v_inv.business_id, v_inv.outlet_id, v_move.product_id, -v_move.qty, 'sale_cancel',
            'sales_invoices', p_invoice_id, 'Cancelled ' || v_inv.invoice_number, v_actor);
  end loop;

  update public.sales_invoices
  set status = 'cancelled', cancelled_at = now(), cancelled_by = v_actor, cancel_reason = trim(p_reason),
      amount_due_paise = 0
  where id = p_invoice_id;

  -- Receipts that have not gone out yet should not be sent for a cancelled bill.
  update public.notification_jobs
  set status = 'failed', last_error = 'Invoice was cancelled before sending'
  where related_table = 'sales_invoices' and related_id = p_invoice_id and status = 'queued';

  perform public.write_audit(v_inv.business_id, v_actor, 'sale.cancelled', 'sales_invoices', p_invoice_id,
    jsonb_build_object('status', 'posted', 'total_paise', v_inv.total_paise),
    jsonb_build_object('status', 'cancelled', 'reason', trim(p_reason), 'invoice_number', v_inv.invoice_number));
end;
$$;

-- ── Credit notes (full or partial returns) ──────────────────────────────────
-- p_items: [{ "invoice_item_id": uuid, "quantity": numeric }]
-- Amounts are pro-rated from the original line. Returning the last remaining
-- quantity of a line credits exactly what is left, so rounding never drifts.

create or replace function public.create_credit_note(
  p_invoice_id uuid,
  p_items jsonb,
  p_reason text,
  p_restock boolean default true,
  p_refund_mode text default 'cash'
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_inv public.sales_invoices;
  v_series public.invoice_series;
  v_today date := public.ist_today();
  v_fy text := public.financial_year(public.ist_today());
  v_number text;
  v_note_id uuid := gen_random_uuid();
  v_req jsonb;
  v_item public.sales_invoice_items;
  v_prev record;
  v_qty numeric;
  v_remaining numeric;
  v_line integer := 0;
  v_taxable bigint; v_cgst bigint; v_sgst bigint; v_igst bigint; v_cess bigint;
  v_sum_taxable bigint := 0; v_sum_cgst bigint := 0; v_sum_sgst bigint := 0;
  v_sum_igst bigint := 0; v_sum_cess bigint := 0;
  v_round_off bigint := 0;
  v_total bigint;
  v_adjust bigint;
  v_fully_returned boolean;
  v_track boolean;
  v_rows jsonb := '[]'::jsonb;
  v_row jsonb;
begin
  select * into v_inv from public.sales_invoices where id = p_invoice_id for update;
  if not found
     or not public.has_perm(v_inv.business_id, 'sales.credit_note')
     or not public.can_access_outlet(v_inv.outlet_id) then
    raise exception 'You are not allowed to issue credit notes' using errcode = '42501';
  end if;
  if v_inv.status = 'cancelled' then
    raise exception 'This bill is cancelled';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A reason is required for a credit note';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Select at least one item to return';
  end if;
  if p_refund_mode is not null and p_refund_mode not in ('cash', 'upi', 'card', 'bank_transfer') then
    raise exception 'Unknown refund mode';
  end if;

  -- Work out every line first.
  for v_req in select * from jsonb_array_elements(p_items) loop
    v_qty := round((v_req ->> 'quantity')::numeric, 3);
    if v_qty is null or v_qty <= 0 then
      continue;
    end if;

    select * into v_item from public.sales_invoice_items
    where id = (v_req ->> 'invoice_item_id')::uuid and invoice_id = p_invoice_id;
    if not found then
      raise exception 'Item does not belong to this bill';
    end if;
    if v_rows @> jsonb_build_array(jsonb_build_object('invoice_item_id', v_item.id)) then
      raise exception 'The same line was listed twice';
    end if;

    select coalesce(sum(quantity), 0) as qty, coalesce(sum(taxable_paise), 0) as taxable,
           coalesce(sum(cgst_paise), 0) as cgst, coalesce(sum(sgst_paise), 0) as sgst,
           coalesce(sum(igst_paise), 0) as igst, coalesce(sum(cess_paise), 0) as cess
    into v_prev from public.credit_note_items where invoice_item_id = v_item.id;

    v_remaining := v_item.quantity - v_prev.qty;
    if v_qty > v_remaining then
      raise exception 'Only % of "%" can still be returned', trim(trailing '.' from trim(trailing '0' from v_remaining::text)), v_item.description;
    end if;

    if v_qty = v_remaining then
      v_taxable := v_item.taxable_paise - v_prev.taxable;
      v_cgst := v_item.cgst_paise - v_prev.cgst;
      v_sgst := v_item.sgst_paise - v_prev.sgst;
      v_igst := v_item.igst_paise - v_prev.igst;
      v_cess := v_item.cess_paise - v_prev.cess;
    else
      v_taxable := least(round(v_item.taxable_paise * v_qty / v_item.quantity)::bigint, v_item.taxable_paise - v_prev.taxable);
      v_cgst := least(round(v_item.cgst_paise * v_qty / v_item.quantity)::bigint, v_item.cgst_paise - v_prev.cgst);
      v_sgst := least(round(v_item.sgst_paise * v_qty / v_item.quantity)::bigint, v_item.sgst_paise - v_prev.sgst);
      v_igst := least(round(v_item.igst_paise * v_qty / v_item.quantity)::bigint, v_item.igst_paise - v_prev.igst);
      v_cess := least(round(v_item.cess_paise * v_qty / v_item.quantity)::bigint, v_item.cess_paise - v_prev.cess);
    end if;

    v_line := v_line + 1;
    v_rows := v_rows || jsonb_build_object(
      'invoice_item_id', v_item.id, 'line_no', v_line, 'product_id', v_item.product_id,
      'description', v_item.description, 'hsn_code', v_item.hsn_code, 'quantity', v_qty,
      'unit_code', v_item.unit_code, 'unit_price_paise', v_item.unit_price_paise,
      'taxable_paise', v_taxable, 'gst_rate', v_item.gst_rate, 'cess_rate', v_item.cess_rate,
      'cgst_paise', v_cgst, 'sgst_paise', v_sgst, 'igst_paise', v_igst, 'cess_paise', v_cess
    );
    v_sum_taxable := v_sum_taxable + v_taxable;
    v_sum_cgst := v_sum_cgst + v_cgst;
    v_sum_sgst := v_sum_sgst + v_sgst;
    v_sum_igst := v_sum_igst + v_igst;
    v_sum_cess := v_sum_cess + v_cess;
  end loop;

  if v_line = 0 then
    raise exception 'Select at least one item to return';
  end if;

  -- When this note returns everything that was left, also give back the bill's round-off.
  select not exists (
    select 1
    from public.sales_invoice_items i
    where i.invoice_id = p_invoice_id
      and i.quantity
          - coalesce((select sum(c.quantity) from public.credit_note_items c where c.invoice_item_id = i.id), 0)
          - coalesce((select sum((r ->> 'quantity')::numeric) from jsonb_array_elements(v_rows) r
                      where (r ->> 'invoice_item_id')::uuid = i.id), 0) > 0
  ) into v_fully_returned;
  if v_fully_returned then
    v_round_off := v_inv.round_off_paise
      - coalesce((select sum(round_off_paise) from public.credit_notes where invoice_id = p_invoice_id), 0);
  end if;

  v_total := v_sum_taxable + v_sum_cgst + v_sum_sgst + v_sum_igst + v_sum_cess + v_round_off;
  if v_total < 0 then
    v_round_off := v_round_off - v_total;
    v_total := 0;
  end if;

  -- First knock the credit off what the customer still owes; refund only the rest.
  v_adjust := least(v_inv.amount_due_paise, v_total);

  v_series := public.lock_series(v_inv.business_id, v_inv.outlet_id, null, 'credit_note', v_fy);
  v_number := public.format_document_number(v_series.prefix, v_fy, v_series.next_number);
  update public.invoice_series set next_number = v_series.next_number + 1 where id = v_series.id;

  insert into public.credit_notes (
    id, business_id, outlet_id, invoice_id, series_id, credit_note_number, financial_year, credit_note_date,
    seller_gstin, reason, restock, is_inter_state,
    taxable_paise, cgst_paise, sgst_paise, igst_paise, cess_paise, round_off_paise, total_paise,
    adjusted_against_due_paise, refund_paise, refund_mode, created_by
  ) values (
    v_note_id, v_inv.business_id, v_inv.outlet_id, p_invoice_id, v_series.id, v_number, v_fy, v_today,
    v_inv.seller_gstin, trim(p_reason), coalesce(p_restock, false), v_inv.is_inter_state,
    v_sum_taxable, v_sum_cgst, v_sum_sgst, v_sum_igst, v_sum_cess, v_round_off, v_total,
    v_adjust, v_total - v_adjust, case when v_total - v_adjust > 0 then coalesce(p_refund_mode, 'cash') else null end,
    v_actor
  );

  for v_row in select * from jsonb_array_elements(v_rows) loop
    insert into public.credit_note_items (
      credit_note_id, business_id, invoice_item_id, line_no, product_id, description, hsn_code, quantity,
      unit_code, unit_price_paise, taxable_paise, gst_rate, cess_rate,
      cgst_paise, sgst_paise, igst_paise, cess_paise, total_paise
    ) values (
      v_note_id, v_inv.business_id, (v_row ->> 'invoice_item_id')::uuid, (v_row ->> 'line_no')::integer,
      nullif(v_row ->> 'product_id', '')::uuid, v_row ->> 'description', v_row ->> 'hsn_code',
      (v_row ->> 'quantity')::numeric, v_row ->> 'unit_code', (v_row ->> 'unit_price_paise')::bigint,
      (v_row ->> 'taxable_paise')::bigint, (v_row ->> 'gst_rate')::numeric, (v_row ->> 'cess_rate')::numeric,
      (v_row ->> 'cgst_paise')::bigint, (v_row ->> 'sgst_paise')::bigint, (v_row ->> 'igst_paise')::bigint,
      (v_row ->> 'cess_paise')::bigint,
      (v_row ->> 'taxable_paise')::bigint + (v_row ->> 'cgst_paise')::bigint + (v_row ->> 'sgst_paise')::bigint
        + (v_row ->> 'igst_paise')::bigint + (v_row ->> 'cess_paise')::bigint
    );

    if coalesce(p_restock, false) and nullif(v_row ->> 'product_id', '') is not null then
      select track_inventory into v_track from public.products where id = (v_row ->> 'product_id')::uuid;
      if coalesce(v_track, false) then
        insert into public.stock_movements (business_id, outlet_id, product_id, quantity_delta, movement_type,
                                            source_table, source_id, note, created_by)
        values (v_inv.business_id, v_inv.outlet_id, (v_row ->> 'product_id')::uuid, (v_row ->> 'quantity')::numeric,
                'sale_return', 'credit_notes', v_note_id, 'Return ' || v_number || ' against ' || v_inv.invoice_number, v_actor);
      end if;
    end if;
  end loop;

  if v_adjust > 0 then
    update public.sales_invoices set amount_due_paise = amount_due_paise - v_adjust where id = p_invoice_id;
  end if;

  perform public.write_audit(v_inv.business_id, v_actor, 'sale.credit_note', 'credit_notes', v_note_id, null,
    jsonb_build_object('credit_note_number', v_number, 'invoice_number', v_inv.invoice_number,
                       'total_paise', v_total, 'reason', trim(p_reason), 'restock', coalesce(p_restock, false)));
  return v_note_id;
end;
$$;

-- ── Collecting a credit (udhaar) sale later ─────────────────────────────────

create or replace function public.record_sale_collection(
  p_invoice_id uuid,
  p_mode text,
  p_amount_paise bigint,
  p_reference text default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_inv public.sales_invoices;
begin
  select * into v_inv from public.sales_invoices where id = p_invoice_id for update;
  if not found
     or not public.has_perm(v_inv.business_id, 'sales.create')
     or not public.can_access_outlet(v_inv.outlet_id)
     or not (public.has_perm(v_inv.business_id, 'sales.view_all') or v_inv.created_by = auth.uid()) then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if v_inv.status = 'cancelled' then
    raise exception 'This bill is cancelled';
  end if;
  if p_mode not in ('cash', 'upi', 'card', 'bank_transfer') then
    raise exception 'Unknown payment mode';
  end if;
  if p_amount_paise is null or p_amount_paise <= 0 then
    raise exception 'Amount must be more than zero';
  end if;
  if p_amount_paise > v_inv.amount_due_paise then
    raise exception 'Only % is due on this bill', to_char(v_inv.amount_due_paise / 100.0, 'FM999999999990.00');
  end if;

  insert into public.sales_payments (invoice_id, business_id, mode, amount_paise, reference, is_collection, created_by)
  values (p_invoice_id, v_inv.business_id, p_mode, p_amount_paise, nullif(trim(coalesce(p_reference, '')), ''), true, auth.uid());

  update public.sales_invoices set amount_due_paise = amount_due_paise - p_amount_paise where id = p_invoice_id;
end;
$$;

-- Owner can switch the public /i/{token} link of an invoice off (and back on).
create or replace function public.set_invoice_public_link(p_invoice_id uuid, p_enabled boolean)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_inv public.sales_invoices;
begin
  select * into v_inv from public.sales_invoices where id = p_invoice_id;
  if not found or not public.has_perm(v_inv.business_id, 'settings.manage') then
    raise exception 'Only the owner can change the public link' using errcode = '42501';
  end if;
  update public.sales_invoices
  set public_token_revoked_at = case when p_enabled then null else now() end
  where id = p_invoice_id;
  perform public.write_audit(v_inv.business_id, auth.uid(),
    case when p_enabled then 'sale.public_link_restored' else 'sale.public_link_revoked' end,
    'sales_invoices', p_invoice_id, null, jsonb_build_object('invoice_number', v_inv.invoice_number));
end;
$$;

-- ── Row Level Security ──────────────────────────────────────────────────────

alter table public.pos_devices          enable row level security;
alter table public.invoice_series       enable row level security;
alter table public.sales_invoices       enable row level security;
alter table public.sales_invoice_items  enable row level security;
alter table public.sales_payments       enable row level security;
alter table public.credit_notes         enable row level security;
alter table public.credit_note_items    enable row level security;

create policy pos_devices_select on public.pos_devices for select to authenticated
  using (public.is_member(business_id) and public.can_access_outlet(outlet_id));
create policy pos_devices_update on public.pos_devices for update to authenticated
  using (public.has_perm(business_id, 'settings.manage'))
  with check (public.has_perm(business_id, 'settings.manage'));

create policy invoice_series_select on public.invoice_series for select to authenticated
  using (public.is_member(business_id) and public.can_access_outlet(outlet_id));
create policy invoice_series_insert on public.invoice_series for insert to authenticated
  with check (public.has_perm(business_id, 'settings.manage'));
create policy invoice_series_update on public.invoice_series for update to authenticated
  using (public.has_perm(business_id, 'settings.manage'))
  with check (public.has_perm(business_id, 'settings.manage'));

-- Financial documents are read-only through the API. A cashier with only
-- sales.view_own sees just the bills they made.
create policy sales_invoices_select on public.sales_invoices for select to authenticated
  using (
    public.can_access_outlet(outlet_id)
    and (
      public.has_perm(business_id, 'sales.view_all')
      or (public.has_perm(business_id, 'sales.view_own') and created_by = (select auth.uid()))
    )
  );

create policy sales_invoice_items_select on public.sales_invoice_items for select to authenticated
  using (exists (select 1 from public.sales_invoices i where i.id = invoice_id));
create policy sales_payments_select on public.sales_payments for select to authenticated
  using (exists (select 1 from public.sales_invoices i where i.id = invoice_id));

create policy credit_notes_select on public.credit_notes for select to authenticated
  using (
    public.can_access_outlet(outlet_id)
    and (
      public.has_perm(business_id, 'sales.view_all')
      or (public.has_perm(business_id, 'sales.view_own') and created_by = (select auth.uid()))
    )
  );
create policy credit_note_items_select on public.credit_note_items for select to authenticated
  using (exists (select 1 from public.credit_notes c where c.id = credit_note_id));


-- ▶ 20261112000600_shipments.sql

-- ════════════════════════════════════════════════════════════════════════════
-- EkDum · 06 · Courier partners and shipment log
-- ════════════════════════════════════════════════════════════════════════════

create table public.courier_partners (
  id                     uuid primary key default gen_random_uuid(),
  business_id            uuid not null references public.businesses (id) on delete cascade,
  name                   text not null check (length(trim(name)) > 0),
  -- e.g. https://example.com/track?awb={awb} — {awb} is replaced with the tracking number.
  tracking_url_template  text check (
    tracking_url_template is null
    or (tracking_url_template ~ '^https?://' and position('{awb}' in tracking_url_template) > 0)
  ),
  is_active              boolean not null default true,
  created_by             uuid references auth.users (id) on delete set null,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now()
);

create unique index courier_partners_name_uniq on public.courier_partners (business_id, lower(name));
create trigger courier_partners_set_updated_at before update on public.courier_partners
  for each row execute function public.set_updated_at();

create table public.shipments (
  id                    uuid primary key default gen_random_uuid(),
  business_id           uuid not null references public.businesses (id) on delete cascade,
  outlet_id             uuid not null references public.outlets (id) on delete restrict,
  invoice_id            uuid references public.sales_invoices (id) on delete set null,
  customer_id           uuid references public.customers (id) on delete set null,
  -- Recipient snapshot.
  recipient_name        text not null check (length(trim(recipient_name)) > 0),
  recipient_phone       text,
  address_line1         text,
  address_line2         text,
  city                  text,
  pincode               text check (pincode is null or pincode ~ '^[1-9][0-9]{5}$'),
  state_code            text check (state_code is null or state_code ~ '^[0-9]{2}$'),
  courier_partner_id    uuid references public.courier_partners (id) on delete restrict,
  tracking_number       text,
  shipped_on            date not null default public.ist_today(),
  package_count         integer not null default 1 check (package_count > 0),
  weight_grams          integer check (weight_grams is null or weight_grams > 0),
  declared_value_paise  bigint check (declared_value_paise is null or declared_value_paise >= 0),
  receipt_photo_paths   text[] not null default '{}',
  status                text not null default 'booked'
                        check (status in ('booked', 'picked_up', 'in_transit', 'delivered', 'rto', 'cancelled')),
  -- Note for the most recent status change; copied into shipment_events by trigger.
  last_status_note      text,
  status_changed_at     timestamptz not null default now(),
  notes                 text,
  created_by            uuid references auth.users (id) on delete set null,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now()
);

create index shipments_business_status_idx on public.shipments (business_id, status, shipped_on desc);
create index shipments_outlet_idx on public.shipments (outlet_id);
create index shipments_tracking_idx on public.shipments (business_id, tracking_number) where tracking_number is not null;
create index shipments_phone_idx on public.shipments (business_id, recipient_phone) where recipient_phone is not null;
create index shipments_invoice_idx on public.shipments (invoice_id);
create index shipments_customer_idx on public.shipments (customer_id);
create index shipments_courier_idx on public.shipments (courier_partner_id);
create trigger shipments_set_updated_at before update on public.shipments
  for each row execute function public.set_updated_at();

create table public.shipment_events (
  id           uuid primary key default gen_random_uuid(),
  shipment_id  uuid not null references public.shipments (id) on delete cascade,
  business_id  uuid not null references public.businesses (id) on delete cascade,
  status       text not null,
  note         text,
  created_by   uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now()
);

create index shipment_events_shipment_idx on public.shipment_events (shipment_id, created_at);
create index shipment_events_business_idx on public.shipment_events (business_id);

create or replace function public.guard_shipments()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if tg_op = 'UPDATE' then
    if new.business_id <> old.business_id then
      raise exception 'A shipment cannot be moved to another business';
    end if;
    if new.status is distinct from old.status then
      new.status_changed_at := now();
    end if;
  end if;

  if new.invoice_id is not null and not exists (
    select 1 from public.sales_invoices i where i.id = new.invoice_id and i.business_id = new.business_id
  ) then
    raise exception 'Invoice does not belong to this business';
  end if;
  if new.courier_partner_id is not null and not exists (
    select 1 from public.courier_partners c where c.id = new.courier_partner_id and c.business_id = new.business_id
  ) then
    raise exception 'Courier partner does not belong to this business';
  end if;
  if not exists (select 1 from public.outlets o where o.id = new.outlet_id and o.business_id = new.business_id) then
    raise exception 'Outlet does not belong to this business';
  end if;
  return new;
end;
$$;

create trigger shipments_guard before insert or update on public.shipments
  for each row execute function public.guard_shipments();

-- Every status change (and creation) becomes a timeline event.
create or replace function public.log_shipment_event()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if tg_op = 'INSERT' or new.status is distinct from old.status then
    insert into public.shipment_events (shipment_id, business_id, status, note, created_by)
    values (new.id, new.business_id, new.status,
            case when tg_op = 'INSERT' then 'Shipment created' else nullif(trim(coalesce(new.last_status_note, '')), '') end,
            coalesce(auth.uid(), new.created_by));
  end if;
  return new;
end;
$$;

create trigger shipments_log_event after insert or update on public.shipments
  for each row execute function public.log_shipment_event();

alter table public.courier_partners  enable row level security;
alter table public.shipments         enable row level security;
alter table public.shipment_events   enable row level security;

create policy courier_partners_select on public.courier_partners for select to authenticated
  using (public.is_member(business_id));
create policy courier_partners_write on public.courier_partners for all to authenticated
  using (public.has_perm(business_id, 'settings.manage'))
  with check (public.has_perm(business_id, 'settings.manage'));

create policy shipments_select on public.shipments for select to authenticated
  using (public.has_perm(business_id, 'shipments.view') and public.can_access_outlet(outlet_id));
create policy shipments_insert on public.shipments for insert to authenticated
  with check (public.has_perm(business_id, 'shipments.create') and public.can_access_outlet(outlet_id));
create policy shipments_update on public.shipments for update to authenticated
  using (public.has_perm(business_id, 'shipments.update') and public.can_access_outlet(outlet_id))
  with check (public.has_perm(business_id, 'shipments.update') and public.can_access_outlet(outlet_id));

create policy shipment_events_select on public.shipment_events for select to authenticated
  using (exists (select 1 from public.shipments s where s.id = shipment_id));


-- ▶ 20261112000700_reports.sql

-- ════════════════════════════════════════════════════════════════════════════
-- EkDum · 07 · Dashboard and report functions
-- ════════════════════════════════════════════════════════════════════════════
-- All dates are IST calendar dates. invoice_date / credit_note_date are stored
-- as IST dates already; timestamps are converted with ist_date().
-- Each function checks the caller's permission and only reads outlets the
-- caller can access (p_outlet_id = null means "all my outlets").

create or replace function public.report_outlets(p_business_id uuid, p_outlet_id uuid)
returns setof uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select o.id
  from public.outlets o
  where o.business_id = p_business_id
    and (p_outlet_id is null or o.id = p_outlet_id)
    and public.can_access_outlet(o.id);
$$;

create or replace function public.assert_can_report(p_business_id uuid)
returns void
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not (public.has_perm(p_business_id, 'reports.view') or public.has_perm(p_business_id, 'dashboard.view')) then
    raise exception 'You are not allowed to view reports' using errcode = '42501';
  end if;
end;
$$;

-- ── Dashboard (one round trip) ──────────────────────────────────────────────

create or replace function public.dashboard_summary(
  p_business_id uuid,
  p_outlet_id uuid,
  p_from date,
  p_to date
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_outlets uuid[];
  v_today date := public.ist_today();
  v_stuck_days integer;
  v_result jsonb;
begin
  if not public.has_perm(p_business_id, 'dashboard.view') then
    raise exception 'You are not allowed to view the dashboard' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_from > p_to or p_to - p_from > 400 then
    raise exception 'Invalid date range';
  end if;

  select coalesce(array_agg(x), '{}') into v_outlets from public.report_outlets(p_business_id, p_outlet_id) x;
  select stuck_shipment_days into v_stuck_days from public.businesses where id = p_business_id;

  with inv as (
    select * from public.sales_invoices i
    where i.business_id = p_business_id and i.outlet_id = any (v_outlets)
      and i.invoice_date between p_from and p_to
  ),
  posted as (select * from inv where status = 'posted'),
  days as (select d::date as day from generate_series(p_from, p_to, interval '1 day') d),
  trend as (
    select d.day, coalesce(sum(p.total_paise), 0)::bigint as total_paise, count(p.id)::int as invoice_count
    from days d left join posted p on p.invoice_date = d.day
    group by d.day
  ),
  modes as (
    select sp.mode, sum(sp.amount_paise)::bigint as amount_paise, count(*)::int as payment_count
    from public.sales_payments sp
    join public.sales_invoices i on i.id = sp.invoice_id
    where sp.business_id = p_business_id and i.outlet_id = any (v_outlets) and i.status = 'posted'
      and sp.received_on between p_from and p_to
    group by sp.mode
  ),
  item_sales as (
    select coalesce(it.product_id::text, it.description) as key, max(it.description) as name,
           sum(it.total_paise)::bigint as revenue_paise, sum(it.quantity) as quantity
    from public.sales_invoice_items it
    join posted p on p.id = it.invoice_id
    group by 1
  ),
  staff as (
    select p.created_by, coalesce(nullif(pr.full_name, ''), pr.email, 'Unknown') as name,
           sum(p.total_paise)::bigint as total_paise, count(*)::int as invoice_count
    from posted p left join public.profiles pr on pr.id = p.created_by
    group by p.created_by, pr.full_name, pr.email
  ),
  low as (
    select pr.id, pr.name, pr.low_stock_threshold as threshold, pr.unit_code,
           coalesce(sum(sl.quantity), 0) as quantity
    from public.products pr
    left join public.stock_levels sl on sl.product_id = pr.id and sl.outlet_id = any (v_outlets)
    where pr.business_id = p_business_id and pr.is_active and pr.track_inventory
      and pr.low_stock_threshold is not null
    group by pr.id
    having coalesce(sum(sl.quantity), 0) <= pr.low_stock_threshold
  ),
  open_shipments as (
    select s.* from public.shipments s
    where s.business_id = p_business_id and s.outlet_id = any (v_outlets)
      and s.status in ('booked', 'picked_up', 'in_transit')
  )
  select jsonb_build_object(
    'range', jsonb_build_object('from', p_from, 'to', p_to),
    'sales', (
      select jsonb_build_object(
        'total_paise', coalesce(sum(total_paise), 0),
        'invoice_count', count(*),
        'average_paise', case when count(*) = 0 then 0 else round(sum(total_paise)::numeric / count(*)) end,
        'tax_paise', coalesce(sum(cgst_paise + sgst_paise + igst_paise + cess_paise), 0),
        'taxable_paise', coalesce(sum(taxable_paise), 0),
        'discount_paise', coalesce(sum(discount_paise), 0),
        'due_paise', coalesce(sum(amount_due_paise), 0)
      ) from posted
    ),
    'cancelled_count', (select count(*) from inv where status = 'cancelled'),
    'credit_notes', (
      select jsonb_build_object('total_paise', coalesce(sum(c.total_paise), 0), 'count', count(*))
      from public.credit_notes c
      where c.business_id = p_business_id and c.outlet_id = any (v_outlets)
        and c.credit_note_date between p_from and p_to
    ),
    'payment_modes', coalesce((select jsonb_agg(to_jsonb(m) order by m.amount_paise desc) from modes m), '[]'::jsonb),
    'trend', coalesce((select jsonb_agg(to_jsonb(t) order by t.day) from trend t), '[]'::jsonb),
    'top_by_revenue', coalesce((
      select jsonb_agg(to_jsonb(x)) from (
        select name, revenue_paise, quantity from item_sales order by revenue_paise desc, name limit 5
      ) x), '[]'::jsonb),
    'top_by_quantity', coalesce((
      select jsonb_agg(to_jsonb(x)) from (
        select name, revenue_paise, quantity from item_sales order by quantity desc, name limit 5
      ) x), '[]'::jsonb),
    'sales_by_staff', coalesce((select jsonb_agg(to_jsonb(s) order by s.total_paise desc) from staff s), '[]'::jsonb),
    'purchases', (
      select jsonb_build_object('total_paise', coalesce(sum(b.total_paise), 0), 'count', count(*))
      from public.purchase_bills b
      where b.business_id = p_business_id and b.outlet_id = any (v_outlets) and b.status = 'posted'
        and b.vendor_invoice_date between p_from and p_to
        and public.has_perm(p_business_id, 'purchases.view')
    ),
    'low_stock', jsonb_build_object(
      'count', (select count(*) from low),
      'items', coalesce((
        select jsonb_agg(to_jsonb(x)) from (select * from low order by quantity - threshold, name limit 8) x
      ), '[]'::jsonb)
    ),
    'shipments', jsonb_build_object(
      'pending_count', (select count(*) from open_shipments),
      'stuck_days', v_stuck_days,
      'stuck_count', (select count(*) from open_shipments where shipped_on <= v_today - v_stuck_days),
      'stuck', coalesce((
        select jsonb_agg(to_jsonb(x)) from (
          select id, recipient_name, tracking_number, status, shipped_on, (v_today - shipped_on) as days_open
          from open_shipments where shipped_on <= v_today - v_stuck_days
          order by shipped_on limit 5
        ) x), '[]'::jsonb)
    ),
    'recent_cancellations', coalesce((
      select jsonb_agg(to_jsonb(x)) from (
        select i.id, i.invoice_number, i.total_paise, i.cancel_reason, i.cancelled_at
        from public.sales_invoices i
        where i.business_id = p_business_id and i.outlet_id = any (v_outlets) and i.status = 'cancelled'
        order by i.cancelled_at desc limit 5
      ) x), '[]'::jsonb),
    'recent_credit_notes', coalesce((
      select jsonb_agg(to_jsonb(x)) from (
        select c.id, c.invoice_id, c.credit_note_number, c.total_paise, c.reason, c.created_at
        from public.credit_notes c
        where c.business_id = p_business_id and c.outlet_id = any (v_outlets)
        order by c.created_at desc limit 5
      ) x), '[]'::jsonb),
    'failed_notifications', (
      select count(*) from public.notification_jobs j
      where j.business_id = p_business_id and j.status = 'failed'
    )
  ) into v_result;

  return v_result;
end;
$$;

-- ── Reports ─────────────────────────────────────────────────────────────────

create or replace function public.report_sales_register(p_business_id uuid, p_outlet_id uuid, p_from date, p_to date)
returns table (
  invoice_id uuid, invoice_date date, invoice_number text, document_type text, status text, outlet_name text,
  customer_name text, customer_phone text, customer_gstin text, supply_type text, place_of_supply_state text,
  is_inter_state boolean, subtotal_paise bigint, discount_paise bigint, taxable_paise bigint, cgst_paise bigint,
  sgst_paise bigint, igst_paise bigint, cess_paise bigint, round_off_paise bigint, total_paise bigint,
  amount_due_paise bigint, payment_modes text, billed_by text, source text
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  perform public.assert_can_report(p_business_id);
  return query
  select i.id, i.invoice_date, i.invoice_number, i.document_type, i.status, o.name,
         i.customer_name, i.customer_phone, i.customer_gstin, i.supply_type, i.place_of_supply_state,
         i.is_inter_state, i.subtotal_paise, i.discount_paise, i.taxable_paise, i.cgst_paise,
         i.sgst_paise, i.igst_paise, i.cess_paise, i.round_off_paise, i.total_paise, i.amount_due_paise,
         (select string_agg(distinct sp.mode, ', ' order by sp.mode) from public.sales_payments sp where sp.invoice_id = i.id),
         coalesce(nullif(pr.full_name, ''), pr.email),
         i.source
  from public.sales_invoices i
  join public.outlets o on o.id = i.outlet_id
  left join public.profiles pr on pr.id = i.created_by
  where i.business_id = p_business_id
    and i.outlet_id in (select public.report_outlets(p_business_id, p_outlet_id))
    and i.invoice_date between p_from and p_to
  order by i.invoice_date, i.created_at;
end;
$$;

create or replace function public.report_item_sales(p_business_id uuid, p_outlet_id uuid, p_from date, p_to date)
returns table (
  product_id uuid, description text, sku text, hsn_code text, unit_code text, quantity numeric,
  taxable_paise bigint, tax_paise bigint, total_paise bigint, invoice_count bigint
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  perform public.assert_can_report(p_business_id);
  return query
  select it.product_id, max(it.description), max(p.sku), max(it.hsn_code), max(it.unit_code), sum(it.quantity),
         sum(it.taxable_paise)::bigint,
         sum(it.cgst_paise + it.sgst_paise + it.igst_paise + it.cess_paise)::bigint,
         sum(it.total_paise)::bigint, count(distinct i.id)
  from public.sales_invoice_items it
  join public.sales_invoices i on i.id = it.invoice_id
  left join public.products p on p.id = it.product_id
  where i.business_id = p_business_id and i.status = 'posted'
    and i.outlet_id in (select public.report_outlets(p_business_id, p_outlet_id))
    and i.invoice_date between p_from and p_to
  group by it.product_id, case when it.product_id is null then it.description end
  order by sum(it.total_paise) desc;
end;
$$;

-- HSN-wise summary of outward supplies (net of nothing: credit notes are reported separately).
create or replace function public.report_hsn_summary(p_business_id uuid, p_outlet_id uuid, p_from date, p_to date)
returns table (
  hsn_code text, unit_code text, gst_rate numeric, quantity numeric, taxable_paise bigint,
  cgst_paise bigint, sgst_paise bigint, igst_paise bigint, cess_paise bigint, total_paise bigint
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  perform public.assert_can_report(p_business_id);
  return query
  select coalesce(it.hsn_code, '(none)'), it.unit_code, it.gst_rate, sum(it.quantity),
         sum(it.taxable_paise)::bigint, sum(it.cgst_paise)::bigint, sum(it.sgst_paise)::bigint,
         sum(it.igst_paise)::bigint, sum(it.cess_paise)::bigint, sum(it.total_paise)::bigint
  from public.sales_invoice_items it
  join public.sales_invoices i on i.id = it.invoice_id
  where i.business_id = p_business_id and i.status = 'posted'
    and i.outlet_id in (select public.report_outlets(p_business_id, p_outlet_id))
    and i.invoice_date between p_from and p_to
  group by coalesce(it.hsn_code, '(none)'), it.unit_code, it.gst_rate
  order by 1, 3;
end;
$$;

create or replace function public.report_purchase_register(p_business_id uuid, p_outlet_id uuid, p_from date, p_to date)
returns table (
  bill_id uuid, vendor_invoice_date date, vendor_invoice_number text, vendor_name text, vendor_gstin text,
  outlet_name text, status text, place_of_supply_state text, taxable_paise bigint, cgst_paise bigint,
  sgst_paise bigint, igst_paise bigint, cess_paise bigint, round_off_paise bigint, total_paise bigint,
  amount_paid_paise bigint, payment_status text
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  perform public.assert_can_report(p_business_id);
  if not public.has_perm(p_business_id, 'purchases.view') then
    raise exception 'You are not allowed to view purchases' using errcode = '42501';
  end if;
  return query
  select b.id, b.vendor_invoice_date, b.vendor_invoice_number, v.name, v.gstin, o.name, b.status,
         b.place_of_supply_state, b.taxable_paise, b.cgst_paise, b.sgst_paise, b.igst_paise, b.cess_paise,
         b.round_off_paise, b.total_paise, b.amount_paid_paise, b.payment_status
  from public.purchase_bills b
  join public.outlets o on o.id = b.outlet_id
  left join public.vendors v on v.id = b.vendor_id
  where b.business_id = p_business_id and b.status in ('posted', 'cancelled')
    and b.outlet_id in (select public.report_outlets(p_business_id, p_outlet_id))
    and b.vendor_invoice_date between p_from and p_to
  order by b.vendor_invoice_date, b.created_at;
end;
$$;

-- Current stock per product and outlet. Stock value is shown only to users who may see cost prices.
create or replace function public.report_stock_summary(p_business_id uuid, p_outlet_id uuid)
returns table (
  product_id uuid, name text, sku text, barcode text, category text, unit_code text, outlet_name text,
  quantity numeric, low_stock_threshold numeric, is_low boolean, sale_price_paise bigint,
  purchase_price_paise bigint, stock_value_paise bigint
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_cost boolean := public.has_perm(p_business_id, 'products.view_cost');
begin
  perform public.assert_can_report(p_business_id);
  return query
  select p.id, p.name, p.sku, p.barcode, c.name, p.unit_code, o.name,
         coalesce(sl.quantity, 0),
         p.low_stock_threshold,
         (p.low_stock_threshold is not null and coalesce(sl.quantity, 0) <= p.low_stock_threshold),
         p.sale_price_paise,
         case when v_cost then pc.purchase_price_paise end,
         case when v_cost then round(coalesce(sl.quantity, 0) * coalesce(pc.purchase_price_paise, 0))::bigint end
  from public.products p
  cross join public.outlets o
  left join public.stock_levels sl on sl.product_id = p.id and sl.outlet_id = o.id
  left join public.product_categories c on c.id = p.category_id
  left join public.product_costs pc on pc.product_id = p.id
  where p.business_id = p_business_id and p.is_active and p.track_inventory
    and o.id in (select public.report_outlets(p_business_id, p_outlet_id))
  order by p.name, o.name;
end;
$$;

create or replace function public.report_stock_movements(p_business_id uuid, p_outlet_id uuid, p_from date, p_to date)
returns table (
  moved_at timestamptz, product_name text, sku text, outlet_name text, movement_type text,
  quantity_delta numeric, unit_code text, reason text, note text, moved_by text
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  perform public.assert_can_report(p_business_id);
  return query
  select m.created_at, p.name, p.sku, o.name, m.movement_type, m.quantity_delta, p.unit_code, m.reason, m.note,
         coalesce(nullif(pr.full_name, ''), pr.email)
  from public.stock_movements m
  join public.products p on p.id = m.product_id
  join public.outlets o on o.id = m.outlet_id
  left join public.profiles pr on pr.id = m.created_by
  where m.business_id = p_business_id
    and m.outlet_id in (select public.report_outlets(p_business_id, p_outlet_id))
    and public.ist_date(m.created_at) between p_from and p_to
  order by m.created_at;
end;
$$;

create or replace function public.report_payment_modes(p_business_id uuid, p_outlet_id uuid, p_from date, p_to date)
returns table (received_on date, mode text, kind text, payment_count bigint, amount_paise bigint)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  perform public.assert_can_report(p_business_id);
  return query
  select sp.received_on, sp.mode, case when sp.is_collection then 'collection' else 'sale' end,
         count(*), sum(sp.amount_paise)::bigint
  from public.sales_payments sp
  join public.sales_invoices i on i.id = sp.invoice_id
  where sp.business_id = p_business_id and i.status = 'posted'
    and i.outlet_id in (select public.report_outlets(p_business_id, p_outlet_id))
    and sp.received_on between p_from and p_to
  group by sp.received_on, sp.mode, sp.is_collection
  order by sp.received_on, sp.mode;
end;
$$;

create or replace function public.report_shipments(p_business_id uuid, p_outlet_id uuid, p_from date, p_to date)
returns table (
  shipment_id uuid, shipped_on date, status text, courier text, tracking_number text, recipient_name text,
  recipient_phone text, city text, pincode text, state_code text, package_count integer, weight_grams integer,
  declared_value_paise bigint, invoice_number text, outlet_name text, status_changed_at timestamptz
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  perform public.assert_can_report(p_business_id);
  return query
  select s.id, s.shipped_on, s.status, cp.name, s.tracking_number, s.recipient_name, s.recipient_phone,
         s.city, s.pincode, s.state_code, s.package_count, s.weight_grams, s.declared_value_paise,
         i.invoice_number, o.name, s.status_changed_at
  from public.shipments s
  join public.outlets o on o.id = s.outlet_id
  left join public.courier_partners cp on cp.id = s.courier_partner_id
  left join public.sales_invoices i on i.id = s.invoice_id
  where s.business_id = p_business_id
    and s.outlet_id in (select public.report_outlets(p_business_id, p_outlet_id))
    and s.shipped_on between p_from and p_to
  order by s.shipped_on, s.created_at;
end;
$$;

create or replace function public.report_credit_notes(p_business_id uuid, p_outlet_id uuid, p_from date, p_to date)
returns table (
  credit_note_id uuid, credit_note_date date, credit_note_number text, invoice_number text, invoice_date date,
  customer_name text, customer_gstin text, reason text, restock boolean, taxable_paise bigint, cgst_paise bigint,
  sgst_paise bigint, igst_paise bigint, cess_paise bigint, round_off_paise bigint, total_paise bigint,
  refund_paise bigint, refund_mode text, outlet_name text
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  perform public.assert_can_report(p_business_id);
  return query
  select c.id, c.credit_note_date, c.credit_note_number, i.invoice_number, i.invoice_date,
         i.customer_name, i.customer_gstin, c.reason, c.restock, c.taxable_paise, c.cgst_paise, c.sgst_paise,
         c.igst_paise, c.cess_paise, c.round_off_paise, c.total_paise, c.refund_paise, c.refund_mode, o.name
  from public.credit_notes c
  join public.sales_invoices i on i.id = c.invoice_id
  join public.outlets o on o.id = c.outlet_id
  where c.business_id = p_business_id
    and c.outlet_id in (select public.report_outlets(p_business_id, p_outlet_id))
    and c.credit_note_date between p_from and p_to
  order by c.credit_note_date, c.created_at;
end;
$$;

-- Outstanding payable per vendor (posted bills not fully paid).
create or replace function public.vendor_payables(p_business_id uuid)
returns table (vendor_id uuid, bill_count bigint, outstanding_paise bigint)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.has_perm(p_business_id, 'purchases.view') then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  return query
  select b.vendor_id, count(*), sum(b.total_paise - b.amount_paid_paise)::bigint
  from public.purchase_bills b
  where b.business_id = p_business_id and b.status = 'posted' and b.payment_status <> 'paid'
    and b.vendor_id is not null
  group by b.vendor_id;
end;
$$;


-- ▶ 20261112000800_storage.sql

-- ════════════════════════════════════════════════════════════════════════════
-- EkDum · 08 · Storage buckets and policies
-- ════════════════════════════════════════════════════════════════════════════
-- Every object path starts with "{business_id}/". Policies check membership
-- and permission for that business.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
  ('logos', 'logos', true, 1048576, array['image/png', 'image/jpeg', 'image/webp']),
  ('purchase-attachments', 'purchase-attachments', false, 10485760,
     array['image/png', 'image/jpeg', 'image/webp', 'application/pdf']),
  ('shipment-receipts', 'shipment-receipts', false, 5242880, array['image/png', 'image/jpeg', 'image/webp']),
  ('invoice-pdfs', 'invoice-pdfs', false, 5242880, array['application/pdf'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- First path segment as a business id (null when it is not a uuid).
create or replace function public.storage_business_id(p_name text)
returns uuid
language plpgsql
immutable
set search_path = public, pg_temp
as $$
begin
  return split_part(p_name, '/', 1)::uuid;
exception when others then
  return null;
end;
$$;

-- logos: public read (bucket is public); only settings managers can write.
create policy ekdum_logos_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'logos' and public.has_perm(public.storage_business_id(name), 'settings.manage'));
create policy ekdum_logos_update on storage.objects for update to authenticated
  using (bucket_id = 'logos' and public.has_perm(public.storage_business_id(name), 'settings.manage'))
  with check (bucket_id = 'logos' and public.has_perm(public.storage_business_id(name), 'settings.manage'));
create policy ekdum_logos_delete on storage.objects for delete to authenticated
  using (bucket_id = 'logos' and public.has_perm(public.storage_business_id(name), 'settings.manage'));
create policy ekdum_logos_select on storage.objects for select to authenticated
  using (bucket_id = 'logos' and public.is_member(public.storage_business_id(name)));

-- purchase-attachments: private.
create policy ekdum_purchase_attachments_select on storage.objects for select to authenticated
  using (bucket_id = 'purchase-attachments' and public.has_perm(public.storage_business_id(name), 'purchases.view'));
create policy ekdum_purchase_attachments_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'purchase-attachments' and public.has_perm(public.storage_business_id(name), 'purchases.create'));
create policy ekdum_purchase_attachments_delete on storage.objects for delete to authenticated
  using (bucket_id = 'purchase-attachments' and public.has_perm(public.storage_business_id(name), 'purchases.create'));

-- shipment-receipts: private.
create policy ekdum_shipment_receipts_select on storage.objects for select to authenticated
  using (bucket_id = 'shipment-receipts' and public.has_perm(public.storage_business_id(name), 'shipments.view'));
create policy ekdum_shipment_receipts_insert on storage.objects for insert to authenticated
  with check (
    bucket_id = 'shipment-receipts'
    and (public.has_perm(public.storage_business_id(name), 'shipments.create')
         or public.has_perm(public.storage_business_id(name), 'shipments.update'))
  );
create policy ekdum_shipment_receipts_delete on storage.objects for delete to authenticated
  using (bucket_id = 'shipment-receipts' and public.has_perm(public.storage_business_id(name), 'shipments.update'));

-- invoice-pdfs: no client policies. Only the server (service role) reads and
-- writes it, and serves files through signed URLs or the public-token route.


-- ▶ 20261112000900_grants.sql

-- ════════════════════════════════════════════════════════════════════════════
-- EkDum · 09 · API privileges
-- ════════════════════════════════════════════════════════════════════════════
-- Explicit grants, so behaviour does not depend on project-level defaults.
--   anon           → nothing in the public schema.
--   authenticated  → table access (always filtered by RLS) + the RPCs listed below.
--   service_role   → everything (server only; never shipped to the browser).
--
-- IMPORTANT for future migrations: Postgres lets PUBLIC (and therefore anon)
-- execute every NEW function by default, and the schema-level revoke below
-- cannot undo that global default. Every later migration must therefore
-- `revoke execute on function … from public, anon, authenticated` for each new
-- function, then grant only what is needed. New tables need RLS + explicit grants.
-- supabase/tests/00_migrations.test.ts fails if anon can execute any function.

revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
revoke execute on all functions in schema public from public, anon, authenticated;
alter default privileges in schema public revoke execute on functions from public, anon, authenticated;

grant usage on schema public to anon, authenticated, service_role;
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
grant execute on all functions in schema public to service_role;

-- ── Tables: read (RLS decides which rows) ───────────────────────────────────
grant select on all tables in schema public to authenticated;
revoke select on public.rate_limits from authenticated;

-- ── Tables: direct writes that RLS policies allow ───────────────────────────
grant update                 on public.profiles            to authenticated;
grant update                 on public.businesses          to authenticated;
grant insert, update         on public.outlets             to authenticated;
grant insert, update, delete on public.roles               to authenticated;
grant insert, delete         on public.role_permissions    to authenticated;
grant update                 on public.business_members    to authenticated;
grant insert, update, delete on public.invitations         to authenticated;
grant insert, update, delete on public.product_categories  to authenticated;
grant insert, update, delete on public.products            to authenticated;
grant insert, update         on public.product_costs       to authenticated;
grant insert, update, delete on public.customers           to authenticated;
grant insert, update, delete on public.vendors             to authenticated;
grant insert, delete         on public.purchase_payments   to authenticated;
grant update                 on public.pos_devices         to authenticated;
grant insert, update         on public.invoice_series      to authenticated;
grant insert, update, delete on public.courier_partners    to authenticated;
grant insert, update         on public.shipments           to authenticated;
-- Everything else (invoices, credit notes, stock, purchase bills, audit log,
-- notification jobs, memberships) is written only by SECURITY DEFINER functions.

-- ── Functions used inside RLS policies and column defaults ──────────────────
grant execute on function public.is_member(uuid)               to authenticated;
grant execute on function public.has_perm(uuid, text)          to authenticated;
grant execute on function public.can_access_outlet(uuid)       to authenticated;
grant execute on function public.can_access_outlet_of(uuid, uuid) to authenticated;
grant execute on function public.shares_business_with(uuid)    to authenticated;
grant execute on function public.storage_business_id(text)     to authenticated;
grant execute on function public.ist_today()                   to authenticated;
grant execute on function public.ist_date(timestamptz)         to authenticated;
grant execute on function public.financial_year(date)          to authenticated;

-- ── RPCs the signed-in user may call (each checks its own permissions) ──────
grant execute on function public.create_business(jsonb)                                  to authenticated;
grant execute on function public.set_member_outlets(uuid, boolean, uuid[])               to authenticated;
grant execute on function public.touch_member_activity(uuid)                             to authenticated;
grant execute on function public.set_opening_stock(uuid, uuid, numeric)                  to authenticated;
grant execute on function public.adjust_stock(uuid, uuid, numeric, text, text)           to authenticated;
grant execute on function public.post_purchase_bill(uuid)                                to authenticated;
grant execute on function public.cancel_purchase_bill(uuid, text)                        to authenticated;
grant execute on function public.retry_notification_job(uuid)                            to authenticated;
grant execute on function public.register_pos_device(uuid, text, text, text)             to authenticated;
grant execute on function public.send_invoice_notification(uuid, text, text)             to authenticated;
grant execute on function public.cancel_sales_invoice(uuid, text)                        to authenticated;
grant execute on function public.create_credit_note(uuid, jsonb, text, boolean, text)    to authenticated;
grant execute on function public.record_sale_collection(uuid, text, bigint, text)        to authenticated;
grant execute on function public.set_invoice_public_link(uuid, boolean)                  to authenticated;
grant execute on function public.dashboard_summary(uuid, uuid, date, date)               to authenticated;
grant execute on function public.report_sales_register(uuid, uuid, date, date)           to authenticated;
grant execute on function public.report_item_sales(uuid, uuid, date, date)               to authenticated;
grant execute on function public.report_hsn_summary(uuid, uuid, date, date)              to authenticated;
grant execute on function public.report_purchase_register(uuid, uuid, date, date)        to authenticated;
grant execute on function public.report_stock_summary(uuid, uuid)                        to authenticated;
grant execute on function public.report_stock_movements(uuid, uuid, date, date)          to authenticated;
grant execute on function public.report_payment_modes(uuid, uuid, date, date)            to authenticated;
grant execute on function public.report_shipments(uuid, uuid, date, date)                to authenticated;
grant execute on function public.report_credit_notes(uuid, uuid, date, date)             to authenticated;
grant execute on function public.vendor_payables(uuid)                                   to authenticated;

-- Server-only (service role): post_sales_invoice, save_purchase_bill,
-- accept_invitation, claim_notification_jobs, complete_notification_job,
-- check_rate_limit and all internal helpers.


-- ▶ 20261113000100_sale_photos.sql

-- ════════════════════════════════════════════════════════════════════════════
-- EkDum · 11 · Photos of the goods handed over on a bill
-- ════════════════════════════════════════════════════════════════════════════
-- Optional proof photos attached to a sales invoice (what was given to the
-- customer), mainly for manual items that are not in the product list.
-- Stored in their own table so posted invoices stay immutable. Rows are
-- append-only; only owners and managers (sales.cancel) can remove a photo,
-- and every removal is written to the audit log.
-- Object path: sale-photos/{business_id}/{invoice_id}/{file}

create table public.sales_invoice_photos (
  id            uuid primary key default gen_random_uuid(),
  business_id   uuid not null references public.businesses (id) on delete cascade,
  invoice_id    uuid not null references public.sales_invoices (id) on delete cascade,
  storage_path  text not null unique,
  created_by    uuid references auth.users (id) on delete set null,
  created_at    timestamptz not null default now(),
  constraint sales_invoice_photos_path_scoped check (
    storage_path like business_id::text || '/' || invoice_id::text || '/%'
    and length(storage_path) <= 300
  )
);

create index sales_invoice_photos_invoice_idx on public.sales_invoice_photos (invoice_id, created_at);
create index sales_invoice_photos_business_idx on public.sales_invoice_photos (business_id);

-- The invoice must belong to the business, and a bill holds at most 10 photos.
create or replace function public.guard_sales_invoice_photos()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if tg_op = 'UPDATE' then
    raise exception 'Bill photos cannot be changed. Remove the photo and add it again.';
  end if;

  if tg_op = 'DELETE' then
    if exists (select 1 from public.businesses b where b.id = old.business_id) then
      perform public.write_audit(old.business_id, auth.uid(), 'sale.photo_removed', 'sales_invoices', old.invoice_id,
        jsonb_build_object('storage_path', old.storage_path, 'added_by', old.created_by, 'added_at', old.created_at), null);
    end if;
    return old;
  end if;

  if not exists (
    select 1 from public.sales_invoices i where i.id = new.invoice_id and i.business_id = new.business_id
  ) then
    raise exception 'Bill not found';
  end if;
  if (select count(*) from public.sales_invoice_photos p where p.invoice_id = new.invoice_id) >= 10 then
    raise exception 'A bill can have at most 10 photos';
  end if;
  return new;
end;
$$;

create trigger sales_invoice_photos_guard before insert or update or delete on public.sales_invoice_photos
  for each row execute function public.guard_sales_invoice_photos();

-- New functions are executable by PUBLIC by default; trigger functions never need to be.
revoke execute on function public.guard_sales_invoice_photos() from public, anon, authenticated;

-- ── Row Level Security ──────────────────────────────────────────────────────

alter table public.sales_invoice_photos enable row level security;

-- Visible exactly when the bill itself is visible (RLS on sales_invoices applies in the subquery).
create policy sales_invoice_photos_select on public.sales_invoice_photos for select to authenticated
  using (exists (select 1 from public.sales_invoices i where i.id = invoice_id));

-- Anyone who can bill may add photos to a bill they can see (a cashier: only their own bills).
create policy sales_invoice_photos_insert on public.sales_invoice_photos for insert to authenticated
  with check (
    public.has_perm(business_id, 'sales.create')
    and created_by = (select auth.uid())
    and exists (
      select 1 from public.sales_invoices i
      where i.id = invoice_id and i.business_id = sales_invoice_photos.business_id and i.status = 'posted'
    )
  );

create policy sales_invoice_photos_delete on public.sales_invoice_photos for delete to authenticated
  using (public.has_perm(business_id, 'sales.cancel') and exists (select 1 from public.sales_invoices i where i.id = invoice_id));

-- Supabase grants ALL on new tables to anon and authenticated by default, and
-- TRUNCATE ignores RLS. Start from nothing, then grant only what the policies cover.
revoke all on public.sales_invoice_photos from public, anon, authenticated;
grant select, insert, delete on public.sales_invoice_photos to authenticated;
grant all on public.sales_invoice_photos to service_role;

-- ── Storage ─────────────────────────────────────────────────────────────────

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
  ('sale-photos', 'sale-photos', false, 5242880, array['image/png', 'image/jpeg', 'image/webp'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Path segment n (1-based) as a uuid, or null when it is not one.
create or replace function public.storage_uuid_segment(p_name text, p_index integer)
returns uuid
language plpgsql
immutable
set search_path = public, pg_temp
as $$
begin
  return split_part(p_name, '/', p_index)::uuid;
exception when others then
  return null;
end;
$$;

revoke execute on function public.storage_uuid_segment(text, integer) from public, anon;
grant execute on function public.storage_uuid_segment(text, integer) to authenticated;

-- Read: when the bill in the path is visible to the user.
create policy ekdum_sale_photos_select on storage.objects for select to authenticated
  using (
    bucket_id = 'sale-photos'
    and exists (
      select 1 from public.sales_invoices i
      where i.id = public.storage_uuid_segment(name, 2) and i.business_id = public.storage_uuid_segment(name, 1)
    )
  );

-- Upload: needs sales.create and a visible, posted bill in the path.
create policy ekdum_sale_photos_insert on storage.objects for insert to authenticated
  with check (
    bucket_id = 'sale-photos'
    and public.has_perm(public.storage_uuid_segment(name, 1), 'sales.create')
    and exists (
      select 1 from public.sales_invoices i
      where i.id = public.storage_uuid_segment(name, 2) and i.business_id = public.storage_uuid_segment(name, 1)
        and i.status = 'posted'
    )
  );

-- Delete: owners and managers only, matching the table policy.
create policy ekdum_sale_photos_delete on storage.objects for delete to authenticated
  using (bucket_id = 'sale-photos' and public.has_perm(public.storage_uuid_segment(name, 1), 'sales.cancel'));


-- ▶ 20261113000200_invoice_format.sql

-- ════════════════════════════════════════════════════════════════════════════
-- EkDum · 12 · Invoice header and signature line
-- ════════════════════════════════════════════════════════════════════════════
-- The bill format shopkeepers already use carries a "what we deal in" line under
-- the shop name (e.g. "Wholesale Dealer in: Stone Settled Exclusive Fancy
-- Jewellery") and signs off with a title such as "Proprietor" or "Partner".

alter table public.businesses
  add column if not exists invoice_tagline text
    check (invoice_tagline is null or length(invoice_tagline) <= 120),
  add column if not exists signatory_label text not null default 'Authorised Signatory'
    check (length(trim(signatory_label)) between 1 and 40);


-- ▶ 20261113000300_quick_items.sql

-- ════════════════════════════════════════════════════════════════════════════
-- EkDum · 13 · Quick billing items
-- ════════════════════════════════════════════════════════════════════════════
-- Preset item buttons for fast billing on a phone: the cashier taps "Necklace",
-- types the rate (and quantity), and the line goes on the bill with the shop's
-- GST rate, HSN code and unit already set. Billed as manual lines (no product,
-- no stock), so a shop can bill without building a product catalogue first.

create table public.quick_items (
  id                  uuid primary key default gen_random_uuid(),
  business_id         uuid not null references public.businesses (id) on delete cascade,
  name                text not null check (length(trim(name)) between 1 and 60),
  gst_rate            numeric(5,2) not null default 0 check (gst_rate >= 0 and gst_rate <= 100),
  hsn_code            text check (hsn_code is null or hsn_code ~ '^([0-9]{4}|[0-9]{6}|[0-9]{8})$'),
  unit_code           text not null default 'PCS' references public.units (code),
  -- Wholesale bills usually quote the rate before GST (the reference bill does).
  price_includes_tax  boolean not null default false,
  default_rate_paise  bigint check (default_rate_paise is null or default_rate_paise > 0),
  sort_order          integer not null default 0,
  is_active           boolean not null default true,
  created_by          uuid references auth.users (id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

create unique index quick_items_name_uniq on public.quick_items (business_id, lower(trim(name)));
create index quick_items_business_idx on public.quick_items (business_id, sort_order) where is_active;
create index quick_items_unit_idx on public.quick_items (unit_code);
create trigger quick_items_set_updated_at before update on public.quick_items
  for each row execute function public.set_updated_at();

-- Keep the list short enough to stay quick on a phone.
create or replace function public.guard_quick_items()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if tg_op = 'UPDATE' and new.business_id <> old.business_id then
    raise exception 'A quick item cannot be moved to another business';
  end if;
  if tg_op = 'INSERT' and (select count(*) from public.quick_items q where q.business_id = new.business_id) >= 60 then
    raise exception 'You can have at most 60 quick items';
  end if;
  return new;
end;
$$;

create trigger quick_items_guard before insert or update on public.quick_items
  for each row execute function public.guard_quick_items();

revoke execute on function public.guard_quick_items() from public, anon, authenticated;

alter table public.quick_items enable row level security;

-- Every member can bill with them; owners and managers (products.manage or settings.manage) maintain them.
create policy quick_items_select on public.quick_items for select to authenticated
  using (public.is_member(business_id));
create policy quick_items_insert on public.quick_items for insert to authenticated
  with check (public.has_perm(business_id, 'products.manage') or public.has_perm(business_id, 'settings.manage'));
create policy quick_items_update on public.quick_items for update to authenticated
  using (public.has_perm(business_id, 'products.manage') or public.has_perm(business_id, 'settings.manage'))
  with check (public.has_perm(business_id, 'products.manage') or public.has_perm(business_id, 'settings.manage'));
create policy quick_items_delete on public.quick_items for delete to authenticated
  using (public.has_perm(business_id, 'products.manage') or public.has_perm(business_id, 'settings.manage'));

-- Supabase grants ALL on new tables by default (and TRUNCATE ignores RLS): start from nothing.
revoke all on public.quick_items from public, anon, authenticated;
grant select, insert, update, delete on public.quick_items to authenticated;
grant all on public.quick_items to service_role;

commit;
